  'Not checked' => 'Non vérifié',
  'We received your receipt, thank you 🌱 We\'ll get back to you about your payment as soon as possible.' => 'Nous avons reçu votre reçu, merci 🌱 Nous vous répondrons dans les plus brefs délais concernant votre paiement.',
  'We received your receipt, thank you 🌱 Your donation is confirmed.' => 'Nous avons reçu votre reçu, merci 🌱 Votre don est confirmé.',
  'We had already received this receipt, thank you 🌱 We\'ll get back to you about your payment as soon as possible.' => 'Nous avions déjà reçu ce reçu, merci 🌱 Nous vous répondrons dans les plus brefs délais concernant votre paiement.',
  'This receipt seems to have been uploaded to our system before. The same receipt cannot be used for a second donation. If you made a different payment, please send that receipt; our team will also check.' => 'Ce reçu semble avoir déjà été téléchargé dans notre système. Le même reçu ne peut pas être utilisé pour un deuxième don. Si vous avez effectué un paiement différent, veuillez envoyer ce reçu ; notre équipe vérifiera également.',
  'We received your receipt. The amount on it (%1$s) does not seem to match your donation amount (%2$s). Could you check it? If you made a different payment, you can write here; our team will also take a look.' => 'Nous avons reçu votre reçu. Le montant qui y figure (%1$s) ne semble pas correspondre au montant de votre don (%2$s). Pourriez-vous le vérifier ? Si vous avez effectué un paiement différent, vous pouvez l\'écrire ici ; notre équipe y jettera également un œil.',
  'We received your receipt, but the recipient on it does not seem to be our association. Donations are only made to our account in the name of "%s". Could you check? Our team will also take a look.' => 'Nous avons bien reçu votre reçu, mais le destinataire qui y figure ne semble pas être notre association. Les dons sont uniquement effectués sur notre compte au nom de «%s». Pourriez-vous vérifier ? Notre équipe y jettera également un œil.',
  'We received your receipt, but the recipient on it does not seem to match our account. Could you check? Our team will also take a look.' => 'Nous avons reçu votre reçu, mais le destinataire qui y figure ne semble pas correspondre à notre compte. Pourriez-vous vérifier ? Notre équipe y jettera également un œil.',
  'The file you sent does not look like a payment receipt. If you have paid, you can send the receipt or a screenshot of the payment screen here.' => 'Le fichier que vous avez envoyé ne ressemble pas à un reçu de paiement. Si vous avez payé, vous pouvez envoyer le reçu ou une capture d\'écran de l\'écran de paiement ici.',
