  '+ New report' => '+ Nouveau rapport',
  'The recipient\'s number comes from Users › Profile › WhatsApp number; permissions from Users › Roles and access (receive reports, view overall report, manage reports). Reports go out at the chosen time; without a server scheduler they are sent on the next site visit or chat panel use.' => 'Le numéro du destinataire provient de Utilisateurs › Profil › Numéro WhatsApp ; autorisations des utilisateurs > Rôles et accès (recevoir des rapports, afficher le rapport global, gérer les rapports). Les rapports sortent à l\'heure choisie ; sans planificateur de serveur, ils sont envoyés lors de la prochaine visite du site ou de l\'utilisation du panneau de discussion.',
  'Invalid phone number.' => 'Numéro de téléphone invalide.',
  'First add a WhatsApp connection under Settings › Connections.' => 'Ajoutez d\'abord une connexion WhatsApp sous Paramètres > Connexions.',
  '%1$s assigned the chat to %2$s' => '%1$sa attribué le chat à%2$s',
  '%s removed the chat assignment' => '%sa supprimé l\'attribution de chat',
  '%s closed the chat' => '%sa fermé le chat',
