  'This message cannot be resent.' => 'Ce message ne peut pas être renvoyé.',
  'Can\'t react to this message.' => 'Je ne peux pas réagir à ce message.',
  'You can only delete your own notes.' => 'Vous ne pouvez supprimer que vos propres notes.',
  'Reply text cannot be empty.' => 'Le texte de la réponse ne peut pas être vide.',
  'Connection not found. Save the settings first.' => 'Connexion introuvable. Enregistrez d\'abord les paramètres.',
  'The message was only image code; it was not sent.' => 'Le message n’était qu’un code image ; il n\'a pas été envoyé.',
  'This contact is blocklisted; no messages are sent. Remove them from the blocklist to write again.' => 'Ce contact est sur liste noire ; aucun message n\'est envoyé. Supprimez-les de la liste de blocage pour réécrire.',
  'Message could not be saved.' => 'Le message n\'a pas pu être enregistré.',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API (version %s) could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => 'Ce contact écrit à partir d\'un numéro WhatsApp masqué (@lid) et l\'API Evolution (version%s) n\'a pas pu envoyer à cette adresse. Mettez à jour le serveur API Evolution vers la version 2.3 ou ultérieure ; si le vrai numéro du contact arrive, le plugin y envoie.',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => 'Ce contact écrit à partir d\'un numéro WhatsApp masqué (@lid) et l\'API Evolution n\'a pas pu envoyer à cette adresse. Mettez à jour le serveur API Evolution vers la version 2.3 ou ultérieure ; si le vrai numéro du contact arrive, le plugin y envoie.',
  'No WhatsApp connection.' => 'Aucune connexion WhatsApp.',
  'Connected ✓' => 'Connecté ✓',
  'Not connected (state: %s). Connect with QR.' => 'Non connecté (état :%s). Connectez-vous avec QR.',
  'Webhook points to this site ✓' => 'Webhook pointe vers ce site ✓',
  'Evolution API version: %s' => 'Version de l\'API Evolution :%s',
  '(old: replies to hidden-number (@lid) contacts may fail, update to 2.3 or later)' => '(ancien : les réponses aux contacts à numéro masqué (@lid) peuvent échouer, mise à jour vers 2.3 ou version ultérieure)',
  'The webhook is not pointed at this site. Press "Set up webhook".' => 'Le webhook n\'est pas pointé vers ce site. Appuyez sur « Configurer le webhook ».',
  'Webhook set up ✓ Incoming messages will now arrive here.' => 'Configuration du Webhook ✓ Les messages entrants arriveront désormais ici.',
  'Importing recent chats, this may take a while…' => 'Importation de discussions récentes, cela peut prendre un certain temps...',
  'Messages stored in Evolution: %s' => 'Messages stockés dans Evolution :%s',
  'Evolution does not store messages, so older messages cannot be loaded. On the Evolution server set DATABASE_SAVE_DATA_NEW_MESSAGE and DATABASE_SAVE_DATA_HISTORIC to true; for older conversations, keep "Sync full history" on in the instance settings when you reconnect the line with QR.' => 'Evolution ne stocke pas les messages, les anciens messages ne peuvent donc pas être chargés. Sur le serveur Evolution, définissez DATABASE_SAVE_DATA_NEW_MESSAGE et DATABASE_SAVE_DATA_HISTORIC sur true ; pour les conversations plus anciennes, laissez « Synchroniser l\'historique complet » activé dans les paramètres de l\'instance lorsque vous reconnectez la ligne avec QR.',
  '%1$s chats, %2$s messages imported ✓' => 'Chats%1$s, messages%2$simportés ✓',
  'Scan this code via WhatsApp › Linked devices › Link a device.' => 'Scannez ce code via WhatsApp › Appareils liés › Associez un appareil.',
  'Pairing code:' => 'Code d\'appariement :',
  'This line is already connected ✓' => 'Cette ligne est déjà connectée ✓',
  'Save the settings first.' => 'Enregistrez d\'abord les paramètres.',
  'Error:' => 'Erreur :',
  'Delete this connection? Chat history is kept.' => 'Supprimer cette connexion ? L\'historique des discussions est conservé.',
  'Asking the AI…' => 'Demander à l’IA...',
  'Working ✓ (%2$s ms): %1$s' => 'Fonctionnement ✓ (%2$sms) :%1$s',
  'Save the key and model first.' => 'Enregistrez d\'abord la clé et le modèle.',
  'Connections' => 'Connexions',
  'Auto replies' => 'Réponses automatiques',
  'AI and assistant' => 'IA et assistant',
  'System check' => 'Vérification du système',
  'Connect your WhatsApp line, manage auto replies and labels.' => 'Connectez votre ligne WhatsApp, gérez les réponses automatiques et les étiquettes.',
  'Open chats' => 'Discussions ouvertes',
  'Settings saved.' => 'Paramètres enregistrés.',
  'Connections and settings the call center needs. Saved status is shown; use the "test" buttons on each tab for a live check. The same checks also appear with the other plugins on the theme\'s system-check screen.' => 'Connexions et paramètres dont le centre d\'appels a besoin. L\'état enregistré est affiché ; utilisez les boutons « test » sur chaque onglet pour une vérification en direct. Les mêmes vérifications apparaissent également avec les autres plugins sur l\'écran de vérification du système du thème.',
  'WhatsApp lines' => 'Lignes WhatsApp',
  'Messages are sent and received through Evolution API. WhatsApp connections are managed in Flux Mail; choose which one to use here. The URL and API key stay there, so you do not need to update them here when they change.' => 'Les messages sont envoyés et reçus via l\'API Evolution. Les connexions WhatsApp sont gérées dans Flux Mail ; choisissez lequel utiliser ici. L\'URL et la clé API restent là, vous n\'avez donc pas besoin de les mettre à jour ici lorsqu\'elles changent.',
  'Communication › Connections' => 'Communication › Connexions',
  'Messages are sent and received via Evolution API. If an Evolution provider is set up in Flux Certificates, you can pick the same connection; the URL and API key stay there.' => 'Les messages sont envoyés et reçus via l\'API Evolution. Si un fournisseur Evolution est configuré dans les Certificats Flux, vous pouvez choisir la même connexion ; l\'URL et la clé API y restent.',
  'Add line' => 'Ajouter une ligne',
  'Setup steps' => 'Étapes de configuration',
  'Add the line and save.' => 'Ajoutez la ligne et enregistrez.',
  'Use "Test connection" to see that Evolution is reachable. If the line is not linked, choose "Connect with QR" and scan it from the phone.' => 'Utilisez « Test de connexion » pour vérifier qu\'Evolution est accessible. Si la ligne n\'est pas liée, choisissez « Se connecter avec QR » et scannez-la depuis le téléphone.',
  'Press "Set up webhook". Incoming messages, and messages sent from the phone and from Flux Certificates, then appear here live.' => 'Appuyez sur « Configurer le webhook ». Les messages entrants, ainsi que les messages envoyés depuis le téléphone et depuis les Certificats Flux, apparaissent alors ici en direct.',
  'Optionally bring in past messages with "Import recent chats".' => 'Si vous le souhaitez, récupérez les messages antérieurs avec « Importer les discussions récentes ».',
  'connected' => 'connecté',
  'connecting' => 'connexion',
  'not connected' => 'non connecté',
  'not on server' => 'pas sur le serveur',
  'unreachable' => 'inaccessible',
  'Flux Mail connection: %s' => 'Connexion Flux Mail :%s',
  'Flux Mail connection #%d (not found or disabled)' => 'Connexion Flux Mail #%d(introuvable ou désactivée)',
  'Use Flux Certificates provider: %s' => 'Utiliser le fournisseur de certificats Flux :%s',
  'Enter separate Evolution API details' => 'Saisir des détails distincts sur l\'API Evolution',
  'Line name (e.g. Main line)' => 'Nom de la ligne (par exemple, ligne principale)',
  'Connection details' => 'Détails de connexion',
  'API URL' => 'URL de l\'API',
  'Instance name' => 'Nom de l\'instance',
  'API key (apikey)' => 'Clé API (apikey)',
  '•••••••• (saved; type to change)' => '•••••••• (enregistré ; saisissez à modifier)',
  'Webhook URL' => 'URL du webhook',
  'Regenerate secret key' => 'Régénérer la clé secrète',
  'Last webhook: %s' => 'Dernier webhook :%s',
  'No webhook received yet.' => 'Aucun webhook reçu pour l\'instant.',
  'Test connection' => 'Tester la connexion',
  'Connect with QR' => 'Connectez-vous avec QR',
  'QR, status and accounts: Communication › Connections' => 'QR, statuts et comptes : Communication › Connexions',
  'Set up webhook' => 'Configurer le webhook',
  'Import recent chats' => 'Importer les discussions récentes',
  'The webhook URL and test buttons appear after saving.' => 'L\'URL du webhook et les boutons de test apparaissent après l\'enregistrement.',
  'Appearance' => 'Apparence',
  'Panel title' => 'Titre du panneau',
  'Site name if empty. The {brand} variable uses this too.' => 'Nom du site s\'il est vide. La variable{brand}l\'utilise également.',
  'Accent color' => 'Couleur d\'accentuation',
  'Behavior' => 'Comportement',
  'Send read receipts (blue ticks) when a chat is opened' => 'Envoyer des accusés de lecture (coches bleues) lorsqu\'un chat est ouvert',
  'Prefix messages with the agent\'s name (*Name:*)' => 'Préfixez les messages avec le nom de l\'agent (*Nom:*)',
  'Agents see only chats assigned to them and unassigned chats (admins see all)' => 'Les agents voient uniquement les chats qui leur sont attribués et les chats non attribués (les administrateurs voient tout)',
  'Also show WhatsApp group messages' => 'Afficher également les messages du groupe WhatsApp',
  'New interface (experimental): the Chats page opens with the same screen as the desktop and mobile app' => 'Nouvelle interface (expérimentale) : la page Chats s\'ouvre avec le même écran que l\'application de bureau et mobile',
  'Live update interval (sec)' => 'Intervalle de mise à jour en direct (sec)',
  'The open tab checks for new messages at this interval (10 recommended). In a background tab it checks once a minute, and less often after errors.' => 'L\'onglet ouvert vérifie les nouveaux messages à cet intervalle (10 recommandés). Dans un onglet en arrière-plan, il vérifie une fois par minute et moins souvent après des erreurs.',
  'Agents' => 'Agents',
  'Give a user the %s role; they see only the chat screen and cannot open settings. Administrators always have access.' => 'Donnez à un utilisateur le rôle%s; ils ne voient que l\'écran de discussion et ne peuvent pas ouvrir les paramètres. Les administrateurs ont toujours accès.',
  'Add new user' => 'Ajouter un nouvel utilisateur',
  'Data' => 'Données',
  'Also delete all chats, messages and media files when the plugin is deleted' => 'Supprimez également tous les chats, messages et fichiers multimédias lorsque le plugin est supprimé',
  'Media files are kept in wp-content/uploads/flx-chat, closed to outside access. They move with uploads when the site is migrated.' => 'Les fichiers multimédias sont conservés dans wp-content/uploads/flx-chat, fermés à l\'accès extérieur. Ils se déplacent avec les téléchargements lorsque le site est migré.',
  'Mon' => 'lundi',
  'Tue' => 'mar.',
  'Wed' => 'mer',
  'Thu' => 'jeu.',
  'Fri' => 'vendredi',
  'Sat' => 'Samedi',
  'Sun' => 'Soleil',
  'Welcome message' => 'Message de bienvenue',
  'Send automatically to people who write to us for the first time' => 'Envoyez automatiquement aux personnes qui nous écrivent pour la première fois',
  'Away message' => 'Message d\'absence',
  'Auto reply to messages received outside business hours' => 'Réponse automatique aux messages reçus en dehors des heures de bureau',
  'Business days' => 'Jours ouvrables',
  'Start' => 'Commencer',
  'End' => 'Fin',
  'At most once per contact every (hours)' => 'Au maximum une fois par contact toutes les (heures)',
  'Timezone: %1$s. Now: %2$s.' => 'Fuseau horaire :%1$s. Maintenant :%2$s.',
  'within business hours' => 'pendant les heures ouvrables',
  'outside business hours' => 'en dehors des heures de bureau',
  'The {first_name}, {name}, {brand}, {site}, {date} variables can be used in the texts.' => 'Les variables{first_name},{name},{brand},{site},{date}peuvent être utilisées dans les textes.',
  'Chat labels' => 'Libellés de discussion',
  'Label chats and filter the list (e.g. Donation, Complaint, Follow-up).' => 'Étiquetez les discussions et filtrez la liste (par exemple, don, plainte, suivi).',
  'Add label' => 'Ajouter une étiquette',
  'Label name' => 'Nom de l\'étiquette',
  'Creating records from chats' => 'Création d\'enregistrements à partir de discussions',
  'Buttons in the chat header create a donation record (Flux Donate) and a certificate (Flux Certificates), and an incoming receipt is matched with a record. If a plugin is not installed, its button is hidden.' => 'Les boutons dans l\'en-tête du chat créent un enregistrement de don (Flux Donate) et un certificat (Flux Certificates), et un reçu entrant est associé à un enregistrement. Si un plugin n\'est pas installé, son bouton est masqué.',
  'Agents can create donation records and match receipts' => 'Les agents peuvent créer des enregistrements de dons et faire correspondre les reçus',
  'Agents can create and send certificates' => 'Les agents peuvent créer et envoyer des certificats',
  'Show quick reply bubbles above the message box' => 'Afficher des bulles de réponse rapide au-dessus de la boîte de message',
  'Donation messages' => 'Messages de don',
  'Ready texts sent to the person when a record is created (editable before sending). If left empty, the default text is used.' => 'Textes prêts envoyés à la personne lors de la création d\'un enregistrement (modifiables avant l\'envoi). S\'il est laissé vide, le texte par défaut est utilisé.',
  'Awaiting payment (promised transfer)' => 'En attente de paiement (virement promis)',
  'Donation received' => 'Don reçu',
  'Receipt confirmed' => 'Réception confirmée',
  'Bank details ({bank})' => 'Coordonnées bancaires ({bank})',
  'Recipient name, bank, IBAN' => 'Nom du destinataire, banque, IBAN',
  'If empty, the account in WooCommerce › Payments › Bank transfer is used.' => 'S\'il est vide, le compte dans WooCommerce › Paiements › Virement bancaire est utilisé.',
  'Variables: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.' => 'Variables :{first_name},{name},{donation},{amount},{quantity},{bank},{certificate_link},{agent},{brand},{date}.',
  'AI connection' => 'Connexion IA',
  'Keys, prompt caching, spending limits and usage logs come from the Flux AI & MCP plugin; all of the Call Center\'s AI requests go through it. Model choices stay here; if a field is empty, the model chosen for this plugin in Flux AI (or the default) is used.' => 'Les clés, la mise en cache des invites, les limites de dépenses et les journaux d\'utilisation proviennent du plugin Flux AI & MCP ; toutes les requêtes IA du Call Center passent par là. Les choix de modèles restent ici ; si un champ est vide, le modèle choisi pour ce plugin dans Flux AI (ou celui par défaut) est utilisé.',
  'Open Flux AI settings' => 'Ouvrir les paramètres de Flux AI',
  'AI needs the Flux AI & MCP plugin. Install and activate it, then enter the OpenRouter and/or Anthropic key in Flux AI & MCP › Settings. Until then suggestions, the assistant, receipt reading, voice messages and summaries are off.' => 'L\'IA a besoin du plugin Flux AI & MCP. Installez-le et activez-le, puis saisissez la clé OpenRouter et/ou Anthropic dans Flux AI & MCP › Paramètres. D\'ici là les suggestions, l\'assistant, la lecture des tickets, les messages vocaux et les résumés sont désactivés.',
  'Creativity (0–1)' => 'Créativité (0-1)',
  'Lower values give more consistent replies, higher values freer ones. 0.4 recommended.' => 'Des valeurs plus faibles donnent des réponses plus cohérentes, des valeurs plus élevées, des réponses plus libres. 0,4 recommandé.',
  'Model (for suggestions)' => 'Modèle (pour suggestions)',
  'Assistant model (optional)' => 'Modèle assistant (facultatif)',
  'Model above' => 'Modèle ci-dessus',
  'Only models that support tools are listed.' => 'Seuls les modèles prenant en charge les outils sont répertoriés.',
  'Receipt reading model (optional)' => 'Modèle de lecture de reçu (facultatif)',
  'If the selected model cannot read images, a cheap vision model is used automatically.' => 'Si le modèle sélectionné ne peut pas lire les images, un modèle de vision bon marché est utilisé automatiquement.',
  'This month (%1$s): %2$s requests, %3$s tokens, about $%4$s.' => 'Ce mois-ci (%1$s) : requêtes%2$s, jetons%3$s, environ $%4$s.',
  'Reply suggestions' => 'Suggestions de réponse',
  'Above the message box, the next message is suggested from the conversation. The agent clicks "Send" or takes it into the box with "Edit". A suggestion is never sent on its own.' => 'Au-dessus de la boîte de message, le message suivant est suggéré à partir de la conversation. L\'agent clique sur "Envoyer" ou le met dans la zone avec "Modifier". Une suggestion n’est jamais envoyée seule.',
  'Prepare a suggestion automatically when the last message came from the person (if off, ask with the ✨ button)' => 'Préparez automatiquement une suggestion lorsque le dernier message est venu de la personne (si désactivé, demandez avec le bouton ✨)',
  'Organization info and tone' => 'Informations sur l\'organisation et ton',
  'E.g. Our association plants saplings in Istanbul. Planting is done every year between November and March. The certificate is sent on WhatsApp after the donation. Use a warm but formal tone.' => 'Par ex. Notre association plante des jeunes arbres à Istanbul. La plantation s\'effectue chaque année entre novembre et mars. L\'attestation est envoyée sur WhatsApp après le don. Utilisez un ton chaleureux mais formel.',
  'Suggestions and the assistant use this. Donation types, prices, bank details and quick replies are added automatically.' => 'Les suggestions et l\'assistant l\'utilisent. Les types de dons, les prix, les coordonnées bancaires et les réponses rapides sont ajoutés automatiquement.',
  'Suggestion provider' => 'Fournisseur de suggestions',
  'Donation assistant (automatic replies)' => 'Assistant de don (réponses automatiques)',
  'When on, the assistant replies itself: it greets, asks the name to address them, sends donation options and prices, optionally collects email and "in whose name", and asks for confirmation after each change. After confirmation it opens an "awaiting payment" record in Flux Donate and sends the donation link, recipient, IBAN and reference as separate messages. If the topic leaves donations, it hands the chat to the team.' => 'Lorsqu\'il est allumé, l\'assistant répond lui-même : il salue, demande le nom pour s\'adresser, envoie les options de don et les prix, collecte éventuellement les e-mails et "au nom de qui", et demande une confirmation après chaque changement. Après confirmation, il ouvre un enregistrement « en attente de paiement » dans Flux Donate et envoie le lien du don, le destinataire, l\'IBAN et la référence dans des messages séparés. Si le sujet laisse des dons, il transmet le chat à l\'équipe.',
  'The Flux Donate plugin is not active; the assistant cannot create donation records.' => 'Le plugin Flux Donate n\'est pas actif ; l\'assistant ne peut pas créer d\'enregistrements de dons.',
  'Instructions, documents, AI chats and test chat' => 'Instructions, documents, discussions IA et discussion de test',
  'Turn on the donation assistant (untick to turn it off everywhere)' => 'Activez l\'assistant de don (décochez-le pour le désactiver partout)',
  'Which chats should it reply to' => 'À quels chats doit-il répondre',
  'In all chats (recommended)' => 'Dans tous les chats (recommandé)',
  'In chats not assigned to an agent' => 'Dans les chats non attribués à un agent',
  'Only outside working hours' => 'Uniquement en dehors des heures de travail',
  'When an agent writes in a chat (from the panel or the phone), the assistant stays quiet there for the time below. Use the assistant button in the chat header to turn it on or off per chat.' => 'Lorsqu\'un agent écrit dans un chat (depuis le panneau ou le téléphone), l\'assistant reste silencieux pendant le temps ci-dessous. Utilisez le bouton Assistant dans l\'en-tête du chat pour l\'activer ou le désactiver par chat.',
  'Test mode: reply only to the numbers below' => 'Mode test : répondez uniquement aux numéros ci-dessous',
  'Test numbers' => 'Numéros de tests',
  'Separate with commas or new lines. Not used when test mode is off.' => 'Séparez par des virgules ou des nouvelles lignes. Non utilisé lorsque le mode test est désactivé.',
  'Quiet after an agent writes (hours)' => 'Calme après qu\'un agent ait écrit (heures)',
  'Quantities in the price list' => 'Quantités dans la liste de prix',
  'Conversation history (hours)' => 'Historique des conversations (heures)',
  'Before replying, the assistant reads all messages from this period.' => 'Avant de répondre, l\'assistant lit tous les messages de cette période.',
  'Donation types the assistant offers' => 'Types de dons proposés par l\'assistant',
  'If none is selected, all open types are offered. When a new type is opened in Flux Donate, the assistant knows it too.' => 'Si aucun n’est sélectionné, tous les types ouverts sont proposés. Lorsqu\'un nouveau type est ouvert dans Flux Donate, l\'assistant le sait également.',
  'Receipt pre-check: when the contact sends a receipt, AI compares the amount, recipient and IBAN with the donation, tells the contact the result, attaches the file to the donation record and hands the chat to the team for final approval (does not mark it paid)' => 'Pré-vérification du reçu : lorsque le contact envoie un reçu, AI compare le montant, le destinataire et l\'IBAN avec le don, informe le contact du résultat, joint le fichier au dossier de don et transmet le chat à l\'équipe pour approbation finale (ne le marque pas comme payé)',
  'Last line of the price list' => 'Dernière ligne de la liste de prix',
  'Payment details' => 'Détails du paiement',
  'If the recipient and IBAN are empty, those in WooCommerce › Payments › Bank transfer are used (the account shown on orders). Fill them in only if the assistant should use a different account.' => 'Si le destinataire et l\'IBAN sont vides, ceux de WooCommerce › Paiements › Virement bancaire sont utilisés (le compte indiqué sur les commandes). Remplissez-les uniquement si l\'assistant doit utiliser un autre compte.',
  'Recipient name' => 'Nom du destinataire',
  'Transfer description' => 'Descriptif du transfert',
  'Variables: {type}, {name}, {amount}, {quantity}' => 'Variables :{type},{name},{amount},{quantity}',
  'Donation page URL' => 'URL de la page de don',
  'The selected type and quantity are added to the link (?flxb_opt=…&flxb_qty=…).' => 'Le type et la quantité sélectionnés sont ajoutés au lien (?flxb_opt=...&flxb_qty=...).',
  'Message after the payment details' => 'Message après les détails du paiement',
  'Donation cancellation question' => 'Question d\'annulation de don',
  'The assistant cancels only unpaid donations, with the person\'s confirmation. Empty = default text. Variables: {bagis}, {tutar}.' => 'L\'assistant n\'annule que les dons impayés, avec confirmation de la personne. Vide = texte par défaut. Variables :{bagis},{tutar}.',
  'Message sent when the daily limit is reached' => 'Message envoyé lorsque la limite journalière est atteinte',
  'Sent once when a chat reaches the day\'s reply limit; the chat is handed to the team. Reset it from the chat\'s ⋮ menu › Assistant usage.' => 'Envoyé une fois lorsqu\'un chat atteint la limite de réponse du jour ; le chat est transmis à l\'équipe. Réinitialisez-le depuis le menu ⋮ du chat › Utilisation de l\'assistant.',
  'Message sent when handing over to the team' => 'Message envoyé lors de la passation de relais à l\'équipe',
  'Message sent when the assistant cannot answer' => 'Message envoyé lorsque l\'assistant ne peut pas répondre',
  'If the AI fails, the time limit is hit or the queue gets too long, this message is sent and the chat is handed to the team; the person is never left without an answer.' => 'Si l\'IA échoue, que le délai est atteint ou que la file d\'attente devient trop longue, ce message est envoyé et le chat est transmis à l\'équipe ; la personne n\'est jamais laissée sans réponse.',
  'Minimum wait before the holding message (s)' => 'Attente minimale avant le(s) message(s) d\'attente',
  'The holding message is not sent until this many seconds after the person\'s message; meanwhile the assistant retries.' => 'Le message d\'attente n\'est envoyé que plusieurs secondes après le message de la personne ; pendant ce temps, l\'assistant réessaye.',
  'Longest time for one answer (s)' => 'Temps le plus long pour une ou plusieurs réponses',
  'Hostinger can cut requests at ~60 s; 50 is recommended.' => 'Hostinger peut réduire les requêtes à environ 60 s ; 50 est recommandé.',
  'Numbers notified on handoff' => 'Numéros notifiés lors du transfert',
  'When the assistant hands a chat over to the team, a WhatsApp message is sent to these numbers from the same line: the contact\'s name, phone, reason, last messages and panel link. Separate with commas or new lines. The assistant does not talk to these numbers.' => 'Lorsque l\'assistant transmet un chat à l\'équipe, un message WhatsApp est envoyé à ces numéros depuis la même ligne : le nom du contact, son téléphone, la raison, les derniers messages et le lien du panneau. Séparez par des virgules ou des nouvelles lignes. L\'assistant ne parle pas à ces numéros.',
  'When the contact writes one of these, the assistant immediately sends the hand-off message above and turns off in that chat. If left empty, the example list is used.' => 'Lorsque le contact en écrit un, l\'assistant envoie immédiatement le message de transfert ci-dessus et s\'éteint dans cette discussion. Si elle est laissée vide, la liste d\'exemples est utilisée.',
  'Extra instructions for the assistant' => 'Instructions supplémentaires pour l\'assistant',
  'E.g. Saplings are planted in Kocaeli. Certificates are sent once the donation is confirmed.' => 'Par ex. Des plants sont plantés à Kocaeli. Les certificats sont envoyés une fois le don confirmé.',
  'Last message when a contact opts out' => 'Dernier message lorsqu\'un contact se désinscrit',
  'If someone writes something like "don\'t message me", the assistant sends this message and blocklists them. A blocklisted person gets no WhatsApp, email or SMS; manage the list under Chats › ☰ › Blocklist.' => 'Si quelqu\'un écrit quelque chose comme « ne m\'envoie pas de message », l\'assistant envoie ce message et le bloque. Une personne inscrite sur la liste bloquée ne reçoit ni WhatsApp, ni e-mail, ni SMS ; gérez la liste sous Chats › ☰ › Liste de blocage.',
  'Contact memory and background jobs' => 'Mémoire de contacts et tâches en arrière-plan',
  'Contact memory: the assistant remembers lasting details (form of address, relatives\' names, numbers, preferences); expired chats are summarized' => 'Mémoire des contacts : l\'assistant se souvient de détails durables (type d\'adresse, noms des proches, numéros, préférences) ; les discussions expirées sont résumées',
  'Summarize a chat after it has been quiet for (hours)' => 'Résumer une conversation après qu\'elle soit restée silencieuse pendant (heures)',
  'Maximum jobs at the same time' => 'Nombre maximum d\'emplois en même temps',
  'How many people can be answered at the same time. Assistant replies always come first; summaries do not start while someone is being answered or waiting. Each job uses one PHP worker: on shared hosting, stay under half of the total worker limit of your sites (e.g. 20-30 of 60 workers).' => 'À combien de personnes peuvent être répondues en même temps. Les réponses de l\'assistant viennent toujours en premier ; les résumés ne démarrent pas lorsque quelqu\'un reçoit une réponse ou attend. Chaque tâche utilise un travailleur PHP : sur un hébergement partagé, restez sous la moitié de la limite totale de travailleurs de vos sites (par exemple 20 à 30 sur 60 travailleurs).',
  'Workers reserved for replies' => 'Ouvriers réservés aux réponses',
  'This many workers never take summaries or reminders.' => 'De nombreux travailleurs ne prennent jamais de résumés ou de rappels.',
  'Summary hours' => 'Heures récapitulatives',
  'Summaries run only between these hours (except a manual "Summarize now"). If both are the same, any time.' => 'Les résumés ne s\'exécutent qu\'entre ces heures (sauf un manuel "Résumer maintenant"). Si les deux sont identiques, à tout moment.',
  'When someone sends a voice message, the assistant turns it into text and replies (the text also appears in the panel as a system line)' => 'Lorsque quelqu\'un envoie un message vocal, l\'assistant le transforme en texte et répond (le texte apparaît également dans le panneau sous forme de ligne système)',
  'Longest voice message (sec)' => 'Message vocal le plus long (sec)',
  'For longer messages the assistant says "the voice message was too long for us to listen to".' => 'Pour les messages plus longs, l\'assistant dit "le message vocal était trop long pour que nous puissions l\'écouter".',
  'Voice message model (optional)' => 'Modèle de message vocal (facultatif)',
  'Cheap audio model (Gemini Flash Lite)' => 'Modèle audio bon marché (Gemini Flash Lite)',
  'Must be an OpenRouter model that accepts audio (Claude does not). An OpenRouter key is required.' => 'Doit être un modèle OpenRouter qui accepte l\'audio (ce n\'est pas le cas de Claude). Une clé OpenRouter est requise.',
  'Images' => 'Images',
  'Let the assistant draw an image when useful (table, report, diagram); it goes to WhatsApp as a picture, the text is sent separately' => 'Laissez l\'assistant dessiner une image lorsque cela est utile (tableau, rapport, diagramme) ; il va sur WhatsApp sous forme d\'image, le texte est envoyé séparément',
  'The Flux AI image renderer is used (Flux AI & MCP › Settings › Images).' => 'Le moteur de rendu d\'image Flux AI est utilisé (Flux AI & MCP › Paramètres › Images).',
  'No image renderer on the server: enter a Gotenberg address in Flux AI & MCP › Settings › Images or install Imagick (SVG). Until then the assistant does not draw images.' => 'Pas de moteur de rendu d\'image sur le serveur : saisissez une adresse Gotenberg dans Flux AI & MCP › Paramètres › Images ou installez Imagick (SVG). Jusque-là, l\'assistant ne dessine pas d\'images.',
  'Works once Flux AI 0.2.0 or later is installed.' => 'Fonctionne une fois que Flux AI 0.2.0 ou version ultérieure est installé.',
  'Donation on behalf of someone' => 'Don au nom de quelqu\'un',
  'If the donation is in someone else\'s name and their number was given (contact card or typed number), also send the certificate to that number on WhatsApp once the payment is approved' => 'Si le don est au nom d\'une autre personne et que son numéro a été donné (carte de contact ou numéro tapé), envoyez également le certificat à ce numéro sur WhatsApp une fois le paiement approuvé.',
  'Message sent before the certificate' => 'Message envoyé avant le certificat',
  'Then the WhatsApp certificate message from Flux Certificates is sent. Variables: {ad}, {bagisci}, {bagis}, {brand}.' => 'Ensuite, le message du certificat WhatsApp de Flux Certificates est envoyé. Variables :{ad},{bagisci},{bagis},{brand}.',
  'If a person asks, the assistant sets up a reminder (e.g. "remind me of sapling planting every month", "send me your latest projects every month", "ask me for a sapling every month"); when it is due, the assistant writes and sends the message' => 'Si une personne le demande, l\'assistant établit un rappel (par exemple "rappelle-moi la plantation d\'un jeune arbre chaque mois", "envoie-moi tes derniers projets chaque mois", "demande-moi un jeune arbre chaque mois"); à l\'échéance, l\'assistant écrit et envoie le message',
  'When no time is given' => 'Quand aucun temps n\'est donné',
  'At most per person' => 'Au maximum par personne',
  'Staff (Flux Roles)' => 'Personnel (rôles flux)',
  'Works once Flux Roles 1.1.0 is installed: users whose number is set in Profile › WhatsApp number get extra assistant tools based on their permissions.' => 'Fonctionne une fois Flux Roles 1.1.0 installé : les utilisateurs dont le numéro est défini dans Profil > Numéro WhatsApp obtiennent des outils d\'assistance supplémentaires en fonction de leurs autorisations.',
  'Give staff numbers extra assistant tools by permission (donation on behalf of someone with payment link, my donors, general report)' => 'Donner aux effectifs des outils d\'assistance supplémentaires avec autorisation (don au nom d\'une personne avec lien de paiement, mes donateurs, rapport général)',
  'Notify staff on WhatsApp when a donation they referred is paid or cancelled' => 'Avertissez le personnel sur WhatsApp lorsqu\'un don qu\'ils ont recommandé est payé ou annulé',
  'First message to the donor for a donation opened by staff' => 'Premier message au donateur pour un don ouvert par le personnel',
  'Hello {ad} 🌱 Your {bagis} donation request via {personel} has been received. You can pay with the details below.' => 'Bonjour{ad}🌱 Votre demande de don{bagis}via{personel}a bien été reçue. Vous pouvez payer avec les détails ci-dessous.',
  'The payment link and bank details follow. Variables: {ad}, {adsoyad}, {personel}, {bagis}.' => 'Le lien de paiement et les coordonnées bancaires suivent. Variables :{ad},{adsoyad},{personel},{bagis}.',
  'When a donation referred by a staff member is paid and its certificates are made, send them to the staff member on WhatsApp too (just like the donor)' => 'Lorsqu\'un don référé par un membre du personnel est payé et que ses attestations sont faites, envoyez-les également au membre du personnel sur WhatsApp (tout comme le donateur)',
  'Message sent to the staff member before the certificate' => 'Message envoyé au membre du personnel avant l\'attestation',
  'Variables: {ad}, {bagisci}, {bagis}, {no}, {brand}.' => 'Variables :{ad},{bagisci},{bagis},{no},{brand}.',
  'How many times staff can resend a donation\'s certificate' => 'Combien de fois le personnel peut-il renvoyer un certificat de don',
  'The assistant lists the recipients and asks for confirmation before sending. 0: off.' => 'L\'assistant liste les destinataires et demande une confirmation avant l\'envoi. 0 : éteint.',
  'Code verification for record lookups' => 'Vérification du code pour les recherches d\'enregistrements',
  'When a person asks for their records and their number is hidden (or they donated with another number/e-mail), send a code to the number or e-mail they give; once verified, its records are shown too' => 'Lorsqu\'une personne demande son dossier et que son numéro est masqué (ou qu\'elle a fait un don avec un autre numéro/e-mail), envoyez un code au numéro ou à l\'e-mail qu\'elle donne ; une fois vérifiés, ses enregistrements sont également affichés',
  'Code validity (min)' => 'Validité du code (min)',
  'Maximum failed attempts' => 'Nombre maximal de tentatives infructueuses',
  'Codes that could not be sent, wrong codes and expired codes count. At the limit the person gets the message below and the team is notified; the assistant keeps answering other questions but shares no record details for 24 hours.' => 'Les codes qui n\'ont pas pu être envoyés, les codes erronés et les codes expirés comptent. A la limite la personne reçoit le message ci-dessous et l\'équipe est avertie ; l\'assistant continue de répondre à d\'autres questions mais ne partage aucun détail d\'enregistrement pendant 24 heures.',
  'Code to phone' => 'Code pour téléphoner',
  'WhatsApp, SMS if it fails' => 'WhatsApp, SMS en cas d\'échec',
  'WhatsApp only' => 'WhatsApp uniquement',
  'SMS only' => 'SMS uniquement',
  'SMS is used if Flux Mail has an SMS connection (e.g. Netgsm).' => 'SMS est utilisé si Flux Mail dispose d\'une connexion SMS (par exemple Netgsm).',
  'Message when verification fails' => 'Message lorsque la vérification échoue',
  'WhatsApp/SMS code message' => 'Message codé WhatsApp/SMS',
  'Default text if empty. Variables: {kod}, {dk}, {marka}. The e-mail text is edited in Flux Mail › E-mail templates.' => 'Texte par défaut s\'il est vide. Variables :{kod},{dk},{marka}. Le texte de l\'e-mail est édité dans Flux Mail › Modèles d\'e-mail.',
  'Site content' => 'Contenu du site',
  'Let the assistant search published site content (e.g. "do you have a post about tree planting")' => 'Laissez l\'assistant rechercher le contenu du site publié (par exemple, "avez-vous un article sur la plantation d\'arbres")',
  'Content types to search' => 'Types de contenu à rechercher',
  'Only published content without a password is returned. Drafts, private and password-protected content are never shown.' => 'Seul le contenu publié sans mot de passe est renvoyé. Les brouillons, le contenu privé et protégé par mot de passe ne sont jamais affichés.',
  'Categories and tags never to share' => 'Catégories et tags à ne jamais partager',
  'e.g. corporate-offers, internal-notice' => 'par ex. offres-corporatives, avis-interne',
  'Name or slug, comma separated. To hide a single item, tick "Do not let the assistant share this content" on its edit screen.' => 'Nom ou limace, séparés par des virgules. Pour masquer un seul élément, cochez « Ne pas laisser l\'assistant partager ce contenu » sur son écran d\'édition.',
