  'Based on average token usage of {n} past scenario results; actual cost per scenario may vary.' => 'Basé sur l\'utilisation moyenne des jetons des résultats du scénario passé{n}; le coût réel par scénario peut varier.',
  'No runs yet; default estimate: ~{i} input / {o} output tokens per donor message.' => 'Aucune course pour l\'instant ; estimation par défaut : ~ jetons d\'entrée{i}/ jetons de sortie{o}par message du donateur.',
  'The estimate exceeds the cost limit; the run stops when the limit is reached.' => 'L\'estimation dépasse la limite de coût ; la course s\'arrête lorsque la limite est atteinte.',
  'New run' => 'Nouvelle course',
  'Scenarios are played like in the test chat: no WhatsApp message is sent and no record is created. The model is really called; the cost is charged to your AI account (OpenRouter or Anthropic) and the run stops when the limit is reached.' => 'Les scénarios se déroulent comme dans le chat test : aucun message WhatsApp n\'est envoyé et aucun enregistrement n\'est créé. Le modèle s\'appelle vraiment ; le coût est facturé sur votre compte AI (OpenRouter ou Anthropic) et la course s\'arrête lorsque la limite est atteinte.',
  'Cost limit (USD)' => 'Limite de coût (USD)',
