  '{tur}, {birim} and {brand} can be used. If there are only customer messages, the assistant replies to each in turn. If you add assistant messages it becomes a continuation scenario: the written history is given as-is and the assistant replies only to the last customer message.' => '{tur},{birim}et{brand}peuvent être utilisés. S\'il n\'y a que des messages clients, l\'assistant répond à chacun à tour de rôle. Si vous ajoutez des messages d\'assistant, cela devient un scénario de continuation : l\'historique écrit est donné tel quel et l\'assistant ne répond qu\'au dernier message client.',
  'E.g. payment_info, cancel_donation, receipt_check. Tools disabled on this site are not checked.' => 'Par ex. payment_info, cancel_donation, reçu_check. Les outils désactivés sur ce site ne sont pas cochés.',
  'Who is writing?' => 'Qui écrit ?',
  'Starting state (test)' => 'État de départ (test)',
  'The scenario runs isolated like the test chat; what you select here exists only in this test. In a customer message, {kod} becomes the verification code from the test panel.' => 'Le scénario s\'exécute de manière isolée comme le chat de test ; ce que vous sélectionnez ici n\'existe que dans ce test. Dans un message client,{kod}devient le code de vérification du panneau de test.',
  'End state' => 'État final',
  'When the conversation ends, the test state is checked (was a donation opened, canceled, a code sent…). Tools disabled on this site are not checked.' => 'A la fin de la conversation, l\'état du test est vérifié (un don a-t-il été ouvert, annulé, un code envoyé...). Les outils désactivés sur ce site ne sont pas cochés.',
  'Judge criterion' => 'Critère du juge',
  'If empty, the judge is not called. Put quality expectations that cannot be written as rules here.' => 'S\'il est vide, le juge n\'est pas appelé. Mettez ici des attentes en matière de qualité qui ne peuvent pas être écrites sous forme de règles.',
