  'Still using the old provider in Flux Certificates; move the connection to Flux Mail and select it here.' => 'Vous utilisez toujours l\'ancien fournisseur dans les certificats Flux ; déplacez la connexion vers Flux Mail et sélectionnez-la ici.',
