  'Phone not connected (state: %1$s, %2$s). Reconnect with "Connect with QR".' => 'Téléphone non connecté (état :%1$s,%2$s). Reconnectez-vous avec « Connecter avec QR ».',
  '%s: Evolution API version' => '%s: Version API Evolution',
  'Evolution API %s is in use. Replies to hidden-number (@lid) contacts may fail; update the server to 2.3 or later.' => 'L\'API Evolution%sest en cours d\'utilisation. Les réponses aux contacts à numéro masqué (@lid) peuvent échouer ; mettez à jour le serveur vers la version 2.3 ou ultérieure.',
  '%s: webhook (incoming messages)' => '%s: webhook (messages entrants)',
  'No events have arrived from Evolution; incoming messages will not show in the panel. Press "Set up webhook".' => 'Aucun événement n\'est arrivé d\'Evolution ; les messages entrants ne s’afficheront pas dans le panneau. Appuyez sur « Configurer le webhook ».',
  'Last event arrived %s. The line may just be quiet; send yourself a message or set up the webhook again to be sure.' => 'Le dernier événement est arrivé%s. La ligne est peut-être simplement silencieuse ; envoyez-vous un message ou configurez à nouveau le webhook pour être sûr.',
  'Last event arrived %s.' => 'Le dernier événement est arrivé%s.',
  'Flux Mail integration' => 'Intégration de Flux Mail',
  'Active: WhatsApp connections are taken from Communication › Connections.' => 'Actif : les connexions WhatsApp proviennent de Communication > Connexions.',
  'Flux Mail is not active; connections are taken from Flux Certificates or from this plugin.' => 'Flux Mail n\'est pas actif ; les connexions sont extraites des Certificats Flux ou de ce plugin.',
  'Flux Certificates integration' => 'Intégration des Certificats Flux',
  'Active: certificates can be created and sent from chats.' => 'Actif : des certificats peuvent être créés et envoyés depuis les chats.',
  'Flux Certificates is not active; certificate actions in chats are off.' => 'Les Certificats Flux ne sont pas actifs ; les actions de certificat dans les discussions sont désactivées.',
  'Flux Donate integration' => 'Intégration de Flux Donate',
  'Active: donation records, receipt matching and the assistant are available from chats.' => 'Actif : les enregistrements de dons, l\'appariement des reçus et l\'assistant sont disponibles depuis les chats.',
  'Flux Donate is not active; donation records, receipt matching and the donation assistant are off.' => 'Flux Donate n’est pas actif ; les enregistrements de dons, l\'appariement des reçus et l\'assistant de don sont désactivés.',
  'The Flux AI & MCP plugin is not installed; AI features (suggestions, assistant, receipt reading, voice messages, summaries) are off. Install Flux AI and enter the key there.' => 'Le plugin Flux AI & MCP n\'est pas installé ; Les fonctionnalités d\'IA (suggestions, assistant, lecture de reçus, messages vocaux, résumés) sont désactivées. Installez Flux AI et entrez la clé ici.',
  'No key has been entered in Flux AI; message suggestions and the assistant are off.' => 'Aucune clé n\'a été saisie dans Flux AI ; les suggestions de messages et l\'assistant sont éteints.',
  'Key saved but no model selected.' => 'Clé enregistrée mais aucun modèle sélectionné.',
  'No provider key has been entered in Flux AI for the selected model (%s).' => 'Aucune clé de fournisseur n\'a été saisie dans Flux AI pour le modèle sélectionné (%s).',
  'Key saved, model: %s. Use "Test connection" for a live check.' => 'Clé enregistrée, modèle :%s. Utilisez « Test de connexion » pour une vérification en direct.',
  'Donation assistant' => 'Assistante aux dons',
  'Off.' => 'Éteint.',
  'AI key or model is missing.' => 'La clé ou le modèle AI est manquant.',
  'On but not replying: ' => 'Allumé mais ne répond pas :',
  'On. Donation types offered: %s.' => 'Allumé. Types de dons proposés :%s.',
  '%s does not support tools; choose a tool-capable model for the assistant.' => '%sne prend pas en charge les outils ; choisissez un modèle capable d’outils pour l’assistant.',
  'Receipt reading model' => 'Modèle de lecture de reçu',
  '%s cannot read images; the receipt pre-check will not work. Choose an image-capable receipt reading model.' => '%sne peut pas lire les images ; la vérification préalable du reçu ne fonctionnera pas. Choisissez un modèle de lecture de reçus compatible avec l’image.',
  'Assistant payment details' => 'Détails de paiement de l\'assistant',
  'Recipient name and IBAN set.' => 'Nom du destinataire et ensemble IBAN.',
  'Recipient name or IBAN missing; bank details cannot be sent after confirmation.' => 'Nom du destinataire ou IBAN manquant ; les coordonnées bancaires ne peuvent pas être envoyées après confirmation.',
  'Donation page link' => 'Lien vers la page de don',
  'Donation page not found; the assistant will not send a link.' => 'Page de don introuvable ; l\'assistant n\'enverra pas de lien.',
  'Background requests' => 'Demandes d\'arrière-plan',
  'The site could not send a background request to itself (%1$s: %2$s). Queued replies and the benchmark may move slowly; a security plugin or the server firewall may be blocking /wp-json/flx-chat/ requests.' => 'Le site n\'a pas pu s\'envoyer une demande en arrière-plan (%1$s:%2$s). Les réponses en file d\'attente et l\'indice de référence peuvent évoluer lentement ; un plugin de sécurité ou le pare-feu du serveur peut bloquer les requêtes /wp-json/flx-chat/.',
  'error' => 'erreur',
  'warning' => 'avertissement',
  'ok' => 'ok',
  'Your {marka} verification code: {kod}' => 'Votre code de vérification{marka}:{kod}',
  'The code is valid for {dk} minutes. Type it in your WhatsApp chat with us. If you did not ask for it, ignore this message.' => 'Le code est valable pour{dk}minutes. Tapez-le dans votre chat WhatsApp avec nous. Si vous ne l\'avez pas demandé, ignorez ce message.',
  'Something went wrong; our team will contact you as soon as possible 🌱 Meanwhile, feel free to ask anything else.' => 'Quelque chose s\'est mal passé ; notre équipe vous contactera dans les plus brefs délais 🌱 En attendant, n\'hésitez pas à demander autre chose.',
  'Verification attempt failed (%1$d/%2$d): %3$s' => 'La tentative de vérification a échoué (%1$d/%2$d) :%3$s',
  'The person wanted to see their records but could not be verified; someone from the team should get in touch' => 'La personne voulait voir ses dossiers mais n\'a pas pu être vérifiée ; quelqu\'un de l\'équipe devrait nous contacter',
  'e-mail could not be sent (check Flux Mail › SMTP settings)' => 'l\'e-mail n\'a pas pu être envoyé (vérifiez Flux Mail › Paramètres SMTP)',
  'The assistant sent a verification code for %1$s (%2$s).' => 'L\'assistant a envoyé un code de vérification pour%1$s(%2$s).',
  'code expired' => 'code expiré',
  'wrong code' => 'mauvais code',
  'The person verified the code for %s; it is added to their record lookups.' => 'La personne a vérifié le code pour%s; il est ajouté à leurs recherches d\'enregistrements.',
  'Claude models cannot read audio; choose an audio-capable OpenRouter model in Settings › AI › Voice message model.' => 'Les modèles Claude ne peuvent pas lire l\'audio ; choisissez un modèle OpenRouter compatible audio dans Paramètres > IA > Modèle de message vocal.',
  'The audio could not be transcribed.' => 'L\'audio n\'a pas pu être transcrit.',
  'The audio file could not be read.' => 'Le fichier audio n\'a pas pu être lu.',
  'Voice message (%1$s) transcribed: %2$s' => 'Message vocal (%1$s) transcrit :%2$s',
  'Voice message (%1$s) could not be processed: %2$s' => 'Le message vocal (%1$s) n\'a pas pu être traité :%2$s',
  'This action is not available on an official WhatsApp Cloud API line.' => 'Cette action n\'est pas disponible sur une ligne officielle de l\'API WhatsApp Cloud.',
  'WhatsApp 24-hour rule: the contact has not written in the last 24 hours, so the Cloud API will not send a free-form message; only an approved template can be sent. Try again once they write.' => 'Règle des 24 heures WhatsApp : le contact n\'a pas écrit au cours des dernières 24 heures, l\'API Cloud n\'enverra donc pas de message libre ; seul un modèle approuvé peut être envoyé. Réessayez une fois qu\'ils auront écrit.',
  'A Cloud API line needs Flux Mail 1.10.0 or later.' => 'Une ligne d\'API Cloud nécessite Flux Mail 1.10.0 ou version ultérieure.',
  'The Cloud API cannot send to this address (hidden number or group).' => 'L\'API Cloud ne peut pas envoyer à cette adresse (numéro ou groupe masqué).',
  'Could not reach the Cloud API account (İletişim › Connections).' => 'Impossible d\'accéder au compte Cloud API (İletişim › Connexions).',
  'A Cloud API line has no QR code; the account is set up in İletişim › Connections.' => 'Une ligne d\'API Cloud n\'a pas de code QR ; le compte est créé dans İletişim › Connexions.',
  'The file could not be prepared.' => 'Le fichier n\'a pas pu être préparé.',
  'Flux AI has no image support.' => 'Flux AI ne prend pas en charge les images.',
  'The image could not be rendered.' => 'L\'image n\'a pas pu être rendue.',
  'The assistant\'s image could not be sent: ' => 'L\'image de l\'assistant n\'a pas pu être envoyée :',
  'Hello {first_name}, we have created your donation record: {donation}, total {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'After paying, you can send the receipt here. Thank you.' => 'Bonjour {first_name} , nous avons créé votre enregistrement de don : {donation} , total {amount} .' . chr(10) . '' . chr(10) . ' {bank} ' . chr(10) . '' . chr(10) . 'Après avoir payé, vous pouvez envoyer le reçu ici. Merci.',
  'Hello {first_name}, your donation has been recorded: {donation}, total {amount}.' . chr(10) . '' . chr(10) . 'Thank you for your support.' => 'Bonjour{first_name}, votre don a été enregistré :{donation}, total{amount}.' . chr(10) . '' . chr(10) . 'Merci pour votre soutien.',
  'The plugin that would run this scenario is inactive.' => 'Le plugin qui exécuterait ce scénario est inactif.',
  'This user is not allowed to use the staff tools.' => 'Cet utilisateur n\'est pas autorisé à utiliser les outils du personnel.',
  '%1$s linked this chat to staff member %2$s' => '%1$sa associé ce chat à un membre du personnel%2$s',
  '%s removed the staff link of this chat' => '%sa supprimé le lien du personnel de ce chat',
  'Chat linked to staff member' => 'Chat lié à un membre du personnel',
  'Staff link removed' => 'Lien vers le personnel supprimé',
  '— Not staff —' => '— Pas le personnel —',
  'WhatsApp hides this person\'s number, so the assistant cannot recognise staff by number. If this person is on your team, link them here and the assistant opens the staff tools.' => 'WhatsApp masque le numéro de cette personne, de sorte que l\'assistant ne peut pas reconnaître le personnel par son numéro. Si cette personne fait partie de votre équipe, associez-la ici et l\'assistant ouvrira les outils du personnel.',
  'The assistant recognises staff by the number in their Flux Roles profile. If the number does not match, you can link them here; in a chat with a known number the number comes first.' => 'L\'assistant reconnaît le personnel par le numéro indiqué dans son profil Flux Roles. Si le numéro ne correspond pas, vous pouvez les lier ici ; dans une conversation avec un numéro connu, le numéro vient en premier.',
  'This channel is not available right now.' => 'Cette chaîne n\'est pas disponible pour le moment.',
  'Site chat' => 'Discussion sur le site',
  'All messages from WhatsApp, site chat and other channels appear here live. Pick a chat on the left.' => 'Tous les messages de WhatsApp, du chat du site et d\'autres canaux apparaissent ici en direct. Choisissez une discussion sur la gauche.',
  '[[\'WhatsApp (Evolution API) call center: see live incoming and outgoing messages, start new chat, canned replies, tags, assignment, internal notes, auto-replies; Donation (Flux Donate) and certificate (Flux Certificates) registration from chat, receipt matching. Artificial intelligence response suggestion and automatic donation assistant with OpenRouter.\', \'tr\']]' => '[[Centre d\'appels WhatsApp (API Evolution) : consultez les messages entrants et sortants en direct, démarrez un nouveau chat, les réponses prédéfinies, les tags, les affectations, les notes internes, les réponses automatiques ; Enregistrement de dons (Flux Donate) et de certificats (Flux Certificates) à partir du chat, correspondance des reçus. Suggestion de réponse par intelligence artificielle et assistant de don automatique avec OpenRouter.',
  'Çağrı Merkezi' => 'Centre d\'appels',
  'Sohbetler' => 'Discussions',
  'AI asistan' => 'Assistant IA',
  'Çağrı Merkezi Ayarları' => 'Paramètres du centre d\'appels',
  'Ayarlar' => 'Paramètres',
  'Çağrı Merkezi için JavaScript gerekli.' => 'JavaScript est requis pour le centre d\'appels.',
  'Bu sayfaya erişim yetkiniz yok.' => 'Vous n\'avez pas la permission d\'accéder à cette page.',
  'Asistanın yazıştığı sohbetleri izleyin, talimatını ve belgelerini düzenleyin, değişiklikleri yayına almadan önce test edin.' => 'Surveillez les discussions gérées par l\'assistant, modifiez ses instructions et ses documents, et testez les modifications avant de les publier.',
