  'Yapay zekâ için Flux AI & MCP eklentisi gerekli; kurup etkinleştirin ve Flux AI & MCP › Ayarlar\'a anahtarı girin.' => 'L\'IA a besoin du plugin Flux AI & MCP ; installez-le et activez-le, puis saisissez la clé dans Flux AI & MCP › Paramètres.',
