  'Model listesi için Flux AI & MCP eklentisi gerekli.' => 'La liste des modèles nécessite le plugin Flux AI & MCP.',
  'Flux Chat: yapay zekâ özellikleri (öneri, asistan, dekont okuma, sesli mesaj, özet) için Flux AI & MCP eklentisi gerekli. Kurup etkinleştirin; Çağrı Merkezi\'nde kayıtlı anahtarlar oraya kendiliğinden aktarılır.' => 'Flux Call Center : les fonctionnalités d\'IA (suggestions, assistant, lecture de reçus, messages vocaux, résumés) nécessitent le plugin Flux AI & MCP. Installez-le et activez-le ; les clés enregistrées dans le Call Center y sont déplacées automatiquement.',
  'Flux Chat: %s anahtarı Flux AI\'de farklı bir anahtar olarak zaten kayıtlı; Flux AI\'deki kullanılıyor. Çağrı Merkezi\'ndeki eski anahtar aktarılmadı ve artık kullanılmıyor.' => 'Flux Call Center : une autre clé%sest déjà enregistrée dans Flux AI et est celle utilisée. L\'ancienne clé du Call Center n\'a pas été déplacée et n\'est plus utilisée.',
  'Flux Chat: yapay zekâ anahtarları Flux AI\'ye aktarıldı. Bundan sonra anahtar, harcama sınırı ve kayıtlar Flux AI\'den yönetilir; model seçimleri Çağrı Merkezi\'nde kalır.' => 'Flux Call Center : les clés AI ont été déplacées vers Flux AI. Désormais, les clés, les limites de dépenses et les journaux sont gérés dans Flux AI ; les choix de modèles restent dans le centre d’appels.',
  'Flux Donate eklentisi etkin değil; asistan bağış türlerini ve fiyatları oradan alır.' => 'Le plugin Flux Donate n\'est pas actif ; l\'assistant en prend les types et les prix des dons.',
