  'Bu dekont daha önce sistemimize yüklenmiş görünüyor. Aynı dekont ikinci bir bağış için kullanılamaz. Farklı bir ödeme yaptıysanız o ödemenin dekontunu gönderebilirsiniz; ekibimiz de ayrıca kontrol edecek.' => 'Ce reçu semble avoir déjà été téléchargé dans notre système. Le même reçu ne peut pas être utilisé pour un deuxième don. Si vous avez effectué un paiement différent, veuillez envoyer ce reçu ; notre équipe vérifiera également.',
  'Dekontunuzu aldık. Dekonttaki tutar (%1$s) bağışınızın tutarıyla (%2$s) uyuşmuyor gibi görünüyor. Kontrol edebilir misiniz? Farklı bir ödeme yaptıysanız buradan yazabilirsiniz, ekibimiz de ayrıca bakacak.' => 'Nous avons reçu votre reçu. Le montant qui y figure (%1$s) ne semble pas correspondre au montant de votre don (%2$s). Pourriez-vous le vérifier ? Si vous avez effectué un paiement différent, vous pouvez l\'écrire ici ; notre équipe y jettera également un œil.',
  'Dekontunuzu aldık, ancak dekonttaki alıcı derneğimiz değil gibi görünüyor. Bağışlarımız yalnız "%s" adına açılmış hesabımıza yapılır. Kontrol edebilir misiniz? Ekibimiz de ayrıca bakacak.' => 'Nous avons bien reçu votre reçu, mais le destinataire qui y figure ne semble pas être notre association. Les dons sont uniquement effectués sur notre compte au nom de «%s». Pourriez-vous vérifier ? Notre équipe y jettera également un œil.',
  'Dekontunuzu aldık, ancak dekonttaki alıcı bilgisi bizim hesabımızla eşleşmiyor gibi görünüyor. Kontrol edebilir misiniz? Ekibimiz de ayrıca bakacak.' => 'Nous avons reçu votre reçu, mais le destinataire qui y figure ne semble pas correspondre à notre compte. Pourriez-vous vérifier ? Notre équipe y jettera également un œil.',
  'Gönderdiğiniz dosya bir ödeme dekontuna benzemiyor. Ödemeyi yaptıysanız dekontu ya da ödeme ekranının görüntüsünü buradan gönderebilirsiniz.' => 'Le fichier que vous avez envoyé ne ressemble pas à un reçu de paiement. Si vous avez payé, vous pouvez envoyer le reçu ou une capture d\'écran de l\'écran de paiement ici.',
