  '+ Yeni rapor' => '+ Nouveau rapport',
  'Alıcının numarası Kullanıcılar › Profil › WhatsApp numarası alanından gelir; yetkiler Kullanıcılar › Roller ve erişim sayfasından (rapor alabilir, genel raporu görebilir, raporları yönetir). Rapor seçilen saatte gider; sunucu zamanlayıcısı yoksa sitenin ilk ziyaretinde ya da sohbet panelinde gönderilir.' => 'Le numéro du destinataire provient de Utilisateurs › Profil › Numéro WhatsApp ; autorisations des utilisateurs > Rôles et accès (recevoir des rapports, afficher le rapport global, gérer les rapports). Les rapports sortent à l\'heure choisie ; sans planificateur de serveur, ils sont envoyés lors de la prochaine visite du site ou de l\'utilisation du panneau de discussion.',
  'Geçersiz telefon numarası.' => 'Numéro de téléphone invalide.',
  'Önce Ayarlar › Bağlantılar bölümünden bir WhatsApp bağlantısı ekleyin.' => 'Ajoutez d\'abord une connexion WhatsApp sous Paramètres > Connexions.',
