  'Bu dosya türü gönderilemez.' => 'Ce type de fichier ne peut pas être envoyé.',
  'Dosya yüklenemedi.' => 'Le fichier n\'a pas pu être téléchargé.',
  'Bu mesaj yeniden gönderilemez.' => 'Ce message ne peut pas être renvoyé.',
  'Bu mesaja tepki verilemez.' => 'Je ne peux pas réagir à ce message.',
  'Yalnız kendi notlarınızı silebilirsiniz.' => 'Vous ne pouvez supprimer que vos propres notes.',
  'Cevap metni boş olamaz.' => 'Le texte de la réponse ne peut pas être vide.',
  'Bağlantı bulunamadı. Önce ayarları kaydedin.' => 'Connexion introuvable. Enregistrez d\'abord les paramètres.',
  'Mesaj yalnız görsel kodundan oluşuyordu; gönderilmedi.' => 'Le message n’était qu’un code image ; il n\'a pas été envoyé.',
  'Bu kişi kara listede; mesaj gönderilmez. Kara listeden çıkarınca yeniden yazabilirsiniz.' => 'Ce contact est sur liste noire ; aucun message n\'est envoyé. Supprimez-les de la liste de blocage pour réécrire.',
  'Mesaj kaydedilemedi.' => 'Le message n\'a pas pu être enregistré.',
  'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API (sürüm %s) bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.' => 'Ce contact écrit à partir d\'un numéro WhatsApp masqué (@lid) et l\'API Evolution (version%s) n\'a pas pu envoyer à cette adresse. Mettez à jour le serveur API Evolution vers la version 2.3 ou ultérieure ; si le vrai numéro du contact arrive, le plugin y envoie.',
  'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.' => 'Ce contact écrit à partir d\'un numéro WhatsApp masqué (@lid) et l\'API Evolution n\'a pas pu envoyer à cette adresse. Mettez à jour le serveur API Evolution vers la version 2.3 ou ultérieure ; si le vrai numéro du contact arrive, le plugin y envoie.',
  'WhatsApp bağlantısı yok.' => 'Aucune connexion WhatsApp.',
  'Bağlı ✓' => 'Connecté ✓',
  'Bağlı değil (durum: %s). QR ile bağlayın.' => 'Non connecté (état :%s). Connectez-vous avec QR.',
  'Webhook bu siteye ayarlı ✓' => 'Webhook pointe vers ce site ✓',
  'Evolution API sürümü: %s' => 'Version de l\'API Evolution :%s',
  '(eski: gizli numaralı (@lid) kişilere cevap gidemeyebilir, 2.3 veya üstüne güncelleyin)' => '(ancien : les réponses aux contacts à numéro masqué (@lid) peuvent échouer, mise à jour vers 2.3 ou version ultérieure)',
  'Webhook bu siteye ayarlı değil. "Webhook\'u kur" düğmesine basın.' => 'Le webhook n\'est pas pointé vers ce site. Appuyez sur « Configurer le webhook ».',
  'Webhook kuruldu ✓ Artık gelen mesajlar buraya düşer.' => 'Configuration du Webhook ✓ Les messages entrants arriveront désormais ici.',
  'Son sohbetler içe aktarılıyor, bu biraz sürebilir…' => 'Importation de discussions récentes, cela peut prendre un certain temps...',
  'Evolution\'da kayıtlı mesaj: %s' => 'Messages stockés dans Evolution :%s',
  'Evolution mesajları kaydetmiyor, bu yüzden eski mesajlar gelemez. Evolution sunucusunda DATABASE_SAVE_DATA_NEW_MESSAGE ve DATABASE_SAVE_DATA_HISTORIC değerlerini true yapın; eski konuşmalar için hattı QR ile yeniden bağlarken instance ayarında "Sync full history" açık olsun.' => 'Evolution ne stocke pas les messages, les anciens messages ne peuvent donc pas être chargés. Sur le serveur Evolution, définissez DATABASE_SAVE_DATA_NEW_MESSAGE et DATABASE_SAVE_DATA_HISTORIC sur true ; pour les conversations plus anciennes, laissez « Synchroniser l\'historique complet » activé dans les paramètres de l\'instance lorsque vous reconnectez la ligne avec QR.',
  '%1$s sohbet, %2$s mesaj içe aktarıldı ✓' => 'Chats%1$s, messages%2$simportés ✓',
  'WhatsApp › Bağlı cihazlar › Cihaz bağla ile bu kodu okutun.' => 'Scannez ce code via WhatsApp › Appareils liés › Associez un appareil.',
  'Eşleştirme kodu:' => 'Code d\'appariement :',
  'Bu hat zaten bağlı ✓' => 'Cette ligne est déjà connectée ✓',
  'Önce ayarları kaydedin.' => 'Enregistrez d\'abord les paramètres.',
  'Hata:' => 'Erreur :',
  'Bu bağlantı silinsin mi? Sohbet geçmişi silinmez.' => 'Supprimer cette connexion ? L\'historique des discussions est conservé.',
  'Yapay zekâya soruluyor…' => 'Demander à l’IA...',
  'Çalışıyor ✓ (%2$s ms): %1$s' => 'Fonctionnement ✓ (%2$sms) :%1$s',
  'Önce anahtarı ve modeli kaydedin.' => 'Enregistrez d\'abord la clé et le modèle.',
  'Bağlantılar' => 'Connexions',
  'Otomatik yanıtlar' => 'Réponses automatiques',
  'Yapay zekâ ve asistan' => 'IA et assistant',
  'Sistem kontrolü' => 'Vérification du système',
  'WhatsApp hattınızı bağlayın, otomatik yanıtları ve etiketleri yönetin.' => 'Connectez votre ligne WhatsApp, gérez les réponses automatiques et les étiquettes.',
  'Sohbetleri aç' => 'Discussions ouvertes',
  'Ayarlar kaydedildi.' => 'Paramètres enregistrés.',
  'Çağrı Merkezi\'nin çalışması için gereken bağlantılar ve ayarlar. Kayıtlı durumlar gösterilir; canlı deneme için ilgili sekmedeki "test et" düğmelerini kullanın. Aynı kontroller temanın sistem kontrolü ekranında diğer eklentilerle birlikte de görünür.' => 'Connexions et paramètres dont le centre d\'appels a besoin. L\'état enregistré est affiché ; utilisez les boutons « test » sur chaque onglet pour une vérification en direct. Les mêmes vérifications apparaissent également avec les autres plugins sur l\'écran de vérification du système du thème.',
  'WhatsApp hatları' => 'Lignes WhatsApp',
  'Mesajlar Evolution API üzerinden gönderilir ve alınır. WhatsApp bağlantıları Flux Mail\'de yönetilir; burada hangisinin kullanılacağını seçin. Adres ve API key orada kalır, değişince burada ayrıca güncellemek gerekmez.' => 'Les messages sont envoyés et reçus via l\'API Evolution. Les connexions WhatsApp sont gérées dans Flux Mail ; choisissez lequel utiliser ici. L\'URL et la clé API restent là, vous n\'avez donc pas besoin de les mettre à jour ici lorsqu\'elles changent.',
  'İletişim › Bağlantılar' => 'Communication › Connexions',
  'Mesajlar Evolution API üzerinden gönderilir ve alınır. Flux Certificates eklentisinde Evolution sağlayıcısı tanımlıysa aynı bağlantıyı seçebilirsiniz; adres ve API key orada kalır.' => 'Les messages sont envoyés et reçus via l\'API Evolution. Si un fournisseur Evolution est configuré dans les Certificats Flux, vous pouvez choisir la même connexion ; l\'URL et la clé API y restent.',
  'Hat ekle' => 'Ajouter une ligne',
  'Kurulum adımları' => 'Étapes de configuration',
  'Hattı ekleyip kaydedin.' => 'Ajoutez la ligne et enregistrez.',
  '"Bağlantıyı test et" ile Evolution\'a ulaşıldığını görün. Hat bağlı değilse "QR ile bağla" deyip telefondan okutun.' => 'Utilisez « Test de connexion » pour vérifier qu\'Evolution est accessible. Si la ligne n\'est pas liée, choisissez « Se connecter avec QR » et scannez-la depuis le téléphone.',
  '"Webhook\'u kur" düğmesine basın. Gelen mesajlar, telefondan ve Flux Certificates\'dan gönderilenler canlı olarak buraya düşer.' => 'Appuyez sur « Configurer le webhook ». Les messages entrants, ainsi que les messages envoyés depuis le téléphone et depuis les Certificats Flux, apparaissent alors ici en direct.',
  'İsterseniz "Son sohbetleri içe aktar" ile geçmiş mesajları getirin.' => 'Si vous le souhaitez, récupérez les messages antérieurs avec « Importer les discussions récentes ».',
