  'Canlı güncelleme sıklığı (sn)' => 'Intervalle de mise à jour en direct (sec)',
  'Açık sekmede bu aralıkla yeni mesaj kontrol edilir (önerilen 10). Sekme arka plandayken dakikada bir, hata olursa giderek seyrekleşir.' => 'L\'onglet ouvert vérifie les nouveaux messages à cet intervalle (10 recommandés). Dans un onglet en arrière-plan, il vérifie une fois par minute et moins souvent après des erreurs.',
