  'Bir kullanıcıya %s rolü verin; yalnız sohbet ekranını görür, ayarlara giremez. Yöneticiler her zaman erişir.' => 'Donnez à un utilisateur le rôle%s; ils ne voient que l\'écran de discussion et ne peuvent pas ouvrir les paramètres. Les administrateurs ont toujours accès.',
