  'mesai dışı' => 'en dehors des heures de bureau',
  'Metinlerde {first_name}, {name}, {brand}, {site}, {date} değişkenleri kullanılabilir.' => 'Les variables{first_name},{name},{brand},{site},{date}peuvent être utilisées dans les textes.',
  'Sohbet etiketleri' => 'Libellés de discussion',
  'Sohbetleri etiketleyip listede filtreleyin (ör. Bağış, Şikâyet, Takip).' => 'Étiquetez les discussions et filtrez la liste (par exemple, don, plainte, suivi).',
  'Etiket ekle' => 'Ajouter une étiquette',
  'Etiket adı' => 'Nom de l\'étiquette',
  'Sohbetten kayıt oluşturma' => 'Création d\'enregistrements à partir de discussions',
  'Sohbet başlığındaki düğmelerle bağış kaydı (Flux Donate) ve sertifika (Flux Certificates) oluşturulur, gelen dekont kayıtla eşleştirilir. Eklenti kurulu değilse ilgili düğme görünmez.' => 'Les boutons dans l\'en-tête du chat créent un enregistrement de don (Flux Donate) et un certificat (Flux Certificates), et un reçu entrant est associé à un enregistrement. Si un plugin n\'est pas installé, son bouton est masqué.',
  'Temsilciler bağış kaydı oluşturabilsin ve dekont eşleştirebilsin' => 'Les agents peuvent créer des enregistrements de dons et faire correspondre les reçus',
  'Temsilciler sertifika oluşturup gönderebilsin' => 'Les agents peuvent créer et envoyer des certificats',
  'Mesaj kutusunun üstünde hazır cevap baloncuklarını göster' => 'Afficher des bulles de réponse rapide au-dessus de la boîte de message',
  'Bağış mesajları' => 'Messages de don',
  'Kayıt oluşturulunca kişiye gönderilecek hazır metinler (gönderimden önce düzenlenebilir). Boş bırakılırsa varsayılan metin kullanılır.' => 'Textes prêts envoyés à la personne lors de la création d\'un enregistrement (modifiables avant l\'envoi). S\'il est laissé vide, le texte par défaut est utilisé.',
  'Ödeme bekleniyor (havale sözü)' => 'En attente de paiement (virement promis)',
  'Bağış alındı' => 'Don reçu',
  'Dekont onaylandı' => 'Réception confirmée',
  'Banka bilgisi ({bank})' => 'Coordonnées bancaires ({bank})',
  'Alıcı adı, banka, IBAN' => 'Nom du destinataire, banque, IBAN',
  'Boşsa WooCommerce › Ödemeler › Havale / EFT ayarındaki hesap kullanılır.' => 'S\'il est vide, le compte dans WooCommerce › Paiements › Virement bancaire est utilisé.',
  'Değişkenler: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.' => 'Variables :{first_name},{name},{donation},{amount},{quantity},{bank},{certificate_link},{agent},{brand},{date}.',
  'Yapay zekâ bağlantısı' => 'Connexion IA',
  'Anahtarlar, prompt önbelleği, harcama sınırı ve kullanım kayıtları Flux AI & MCP eklentisinden gelir; Çağrı Merkezi\'nin tüm yapay zekâ istekleri oradan geçer. Model seçimleri burada kalır; alanlar boşsa Flux AI\'de bu eklentiye seçilen model (ya da varsayılan) kullanılır.' => 'Les clés, la mise en cache des invites, les limites de dépenses et les journaux d\'utilisation proviennent du plugin Flux AI & MCP ; toutes les requêtes IA du Call Center passent par là. Les choix de modèles restent ici ; si un champ est vide, le modèle choisi pour ce plugin dans Flux AI (ou celui par défaut) est utilisé.',
  'Flux AI ayarlarını aç' => 'Ouvrir les paramètres de Flux AI',
  'Yapay zekâ için Flux AI & MCP eklentisi gerekli. Kurup etkinleştirin ve Flux AI & MCP › Ayarlar\'a OpenRouter ve/veya Anthropic anahtarını girin. O zamana kadar öneri, asistan, dekont okuma, sesli mesaj ve özet kapalıdır.' => 'L\'IA a besoin du plugin Flux AI & MCP. Installez-le et activez-le, puis saisissez la clé OpenRouter et/ou Anthropic dans Flux AI & MCP › Paramètres. D\'ici là les suggestions, l\'assistant, la lecture des tickets, les messages vocaux et les résumés sont désactivés.',
  'Yaratıcılık (0–1)' => 'Créativité (0-1)',
  'Düşük değer daha tutarlı, yüksek değer daha serbest cevap verir. Önerilen 0,4.' => 'Des valeurs plus faibles donnent des réponses plus cohérentes, des valeurs plus élevées, des réponses plus libres. 0,4 recommandé.',
  'Model (öneriler için)' => 'Modèle (pour suggestions)',
  'Asistan modeli (isteğe bağlı)' => 'Modèle assistant (facultatif)',
  'Yukarıdaki model' => 'Modèle ci-dessus',
  'Yalnız araç (tools) destekleyen modeller listelenir.' => 'Seuls les modèles prenant en charge les outils sont répertoriés.',
  'Dekont okuma modeli (isteğe bağlı)' => 'Modèle de lecture de reçu (facultatif)',
  'Seçilen model görsel okuyamıyorsa görsel okuyan ucuz bir modele kendiliğinden geçilir.' => 'Si le modèle sélectionné ne peut pas lire les images, un modèle de vision bon marché est utilisé automatiquement.',
  'Bu ay (%1$s): %2$s istek, %3$s token, yaklaşık $%4$s.' => 'Ce mois-ci (%1$s) : requêtes%2$s, jetons%3$s, environ $%4$s.',
  'Cevap önerisi' => 'Suggestions de réponse',
  'Mesaj kutusunun üstünde, konuşmaya göre sıradaki mesaj önerilir. Temsilci "Gönder" der ya da "Düzenle" ile kutuya alıp değiştirir. Öneri asla kendiliğinden gönderilmez.' => 'Au-dessus de la boîte de message, le message suivant est suggéré à partir de la conversation. L\'agent clique sur "Envoyer" ou le met dans la zone avec "Modifier". Une suggestion n’est jamais envoyée seule.',
  'Son mesaj kişiden geldiyse öneri kendiliğinden hazırlansın (kapalıysa ✨ düğmesiyle istenir)' => 'Préparez automatiquement une suggestion lorsque le dernier message est venu de la personne (si désactivé, demandez avec le bouton ✨)',
  'Kurum bilgisi ve üslup' => 'Informations sur l\'organisation et ton',
  'Ör. Derneğimiz İstanbul\'da fidan dikimi yapar. Dikimler her yıl Kasım–Mart arasında yapılır. Sertifika bağıştan sonra WhatsApp\'tan gönderilir. Samimi ama resmi bir dil kullan.' => 'Par ex. Notre association plante des jeunes arbres à Istanbul. La plantation s\'effectue chaque année entre novembre et mars. L\'attestation est envoyée sur WhatsApp après le don. Utilisez un ton chaleureux mais formel.',
  'Öneri ve asistan bu bilgileri kullanır. Bağış türleri, fiyatlar, banka bilgisi ve hazır cevaplar ayrıca otomatik eklenir.' => 'Les suggestions et l\'assistant l\'utilisent. Les types de dons, les prix, les coordonnées bancaires et les réponses rapides sont ajoutés automatiquement.',
  'Öneri sağlayıcısı' => 'Fournisseur de suggestions',
  'Bağış asistanı (otomatik cevap)' => 'Assistant de don (réponses automatiques)',
  'Açıkken asistan gelen mesajlara kendisi cevap verir: karşılar, hitap için adını sorar, bağış seçeneklerini ve fiyatları gönderir, isteğe bağlı e-posta ve "kimin adına" bilgilerini alır, her değişiklikte özet gösterip onay ister. Onaydan sonra Flux Donate\'ta "ödeme bekleniyor" kaydı açar ve bağış linki ile alıcı adı, IBAN, açıklamayı ayrı mesajlar hâlinde gönderir. Konu bağış dışına çıkarsa sohbeti ekibe devreder.' => 'Lorsqu\'il est allumé, l\'assistant répond lui-même : il salue, demande le nom pour s\'adresser, envoie les options de don et les prix, collecte éventuellement les e-mails et "au nom de qui", et demande une confirmation après chaque changement. Après confirmation, il ouvre un enregistrement « en attente de paiement » dans Flux Donate et envoie le lien du don, le destinataire, l\'IBAN et la référence dans des messages séparés. Si le sujet laisse des dons, il transmet le chat à l\'équipe.',
  'Flux Donate eklentisi etkin değil; asistan bağış kaydı açamaz.' => 'Le plugin Flux Donate n\'est pas actif ; l\'assistant ne peut pas créer d\'enregistrements de dons.',
  'Talimat, belgeler, AI sohbetleri ve test sohbeti' => 'Instructions, documents, discussions IA et discussion de test',
  'Bağış asistanını aç (tümünü kapatmak için işareti kaldırın)' => 'Activez l\'assistant de don (décochez-le pour le désactiver partout)',
  'Hangi sohbetlerde cevap versin' => 'À quels chats doit-il répondre',
  'Tüm sohbetlerde (önerilen)' => 'Dans tous les chats (recommandé)',
  'Temsilciye atanmamış sohbetlerde' => 'Dans les chats non attribués à un agent',
  'Yalnız mesai saatleri dışında' => 'Uniquement en dehors des heures de travail',
  'Bir temsilci sohbete yazdığında (panelden ya da telefondan) asistan o sohbette aşağıdaki süre kadar susar. Sohbet başlığındaki asistan düğmesiyle sohbet bazında açılıp kapatılır.' => 'Lorsqu\'un agent écrit dans un chat (depuis le panneau ou le téléphone), l\'assistant reste silencieux pendant le temps ci-dessous. Utilisez le bouton Assistant dans l\'en-tête du chat pour l\'activer ou le désactiver par chat.',
  'Test modu: yalnız aşağıdaki numaralarda cevap ver' => 'Mode test : répondez uniquement aux numéros ci-dessous',
  'Test numaraları' => 'Numéros de tests',
  'Virgül ya da satır ile ayırın. Test modu kapalıyken kullanılmaz.' => 'Séparez par des virgules ou des nouvelles lignes. Non utilisé lorsque le mode test est désactivé.',
  'Temsilci yazınca susma (saat)' => 'Calme après qu\'un agent ait écrit (heures)',
  'Fiyat listesindeki adetler' => 'Quantités dans la liste de prix',
  'Konuşma geçmişi (saat)' => 'Historique des conversations (heures)',
  'Asistan cevaptan önce bu süredeki tüm mesajları okur.' => 'Avant de répondre, l\'assistant lit tous les messages de cette période.',
  'Asistanın sunduğu bağış türleri' => 'Types de dons proposés par l\'assistant',
  'Hiçbiri seçilmezse açık olan tüm türler sunulur. Yeni tür Flux Donate\'ta açıldığında asistan onu da bilir.' => 'Si aucun n’est sélectionné, tous les types ouverts sont proposés. Lorsqu\'un nouveau type est ouvert dans Flux Donate, l\'assistant le sait également.',
  'Dekont ön kontrolü: kişi dekont gönderince yapay zekâ tutarı, alıcıyı ve IBAN\'ı bağışla karşılaştırır, sonucu kişiye söyler, dosyayı bağış kaydına ekler ve son onay için sohbeti ekibe devreder (ödendi işaretlemez)' => 'Pré-vérification du reçu : lorsque le contact envoie un reçu, AI compare le montant, le destinataire et l\'IBAN avec le don, informe le contact du résultat, joint le fichier au dossier de don et transmet le chat à l\'équipe pour approbation finale (ne le marque pas comme payé)',
  'Fiyat listesinin son satırı' => 'Dernière ligne de la liste de prix',
  'Ödeme bilgileri' => 'Détails du paiement',
  'Alıcı adı ve IBAN boşsa WooCommerce › Ödemeler › Havale / EFT ayarındakiler kullanılır (siparişlerde görünen hesap). Yalnız asistan için farklı hesap istiyorsanız doldurun.' => 'Si le destinataire et l\'IBAN sont vides, ceux de WooCommerce › Paiements › Virement bancaire sont utilisés (le compte indiqué sur les commandes). Remplissez-les uniquement si l\'assistant doit utiliser un autre compte.',
  'Alıcı adı' => 'Nom du destinataire',
  'Havale açıklaması' => 'Descriptif du transfert',
  'Değişkenler: {type}, {name}, {amount}, {quantity}' => 'Variables :{type},{name},{amount},{quantity}',
  'Bağış sayfası adresi' => 'URL de la page de don',
  'Linke seçilen tür ve adet eklenir (?flxb_opt=…&flxb_qty=…).' => 'Le type et la quantité sélectionnés sont ajoutés au lien (?flxb_opt=...&flxb_qty=...).',
  'Ödeme bilgilerinden sonraki mesaj' => 'Message après les détails du paiement',
  'Bağış iptali onay sorusu' => 'Question d\'annulation de don',
  'Asistan yalnız ödenmemiş bağışları, kişinin onayıyla iptal eder. Boşsa varsayılan metin. Değişkenler: {bagis}, {tutar}.' => 'L\'assistant n\'annule que les dons impayés, avec confirmation de la personne. Vide = texte par défaut. Variables :{bagis},{tutar}.',
  'Günlük sınır dolunca gönderilen mesaj' => 'Message envoyé lorsque la limite journalière est atteinte',
  'Sohbet o günkü cevap sınırına ulaşınca bir kez gider, sohbet ekibe devredilir. Sınır sohbetin ⋮ menüsü › Asistan kullanımı ekranından sıfırlanır.' => 'Envoyé une fois lorsqu\'un chat atteint la limite de réponse du jour ; le chat est transmis à l\'équipe. Réinitialisez-le depuis le menu ⋮ du chat › Utilisation de l\'assistant.',
  'Ekibe devrederken gönderilen mesaj' => 'Message envoyé lors de la passation de relais à l\'équipe',
  'Asistan cevap veremezse giden mesaj' => 'Message envoyé lorsque l\'assistant ne peut pas répondre',
  'Yapay zekâ hata verir, süre aşılır ya da yoğunlukta sıra çok uzarsa kişiye bu mesaj gider ve sohbet ekibe devredilir; kişi hiçbir durumda cevapsız kalmaz.' => 'Si l\'IA échoue, que le délai est atteint ou que la file d\'attente devient trop longue, ce message est envoyé et le chat est transmis à l\'équipe ; la personne n\'est jamais laissée sans réponse.',
  'Bekleme mesajından önce en az (sn)' => 'Attente minimale avant le(s) message(s) d\'attente',
  'Kişinin mesajından bu kadar saniye geçmeden bekleme mesajı gitmez; bu arada asistan yeniden dener.' => 'Le message d\'attente n\'est envoyé que plusieurs secondes après le message de la personne ; pendant ce temps, l\'assistant réessaye.',
  'Bir cevabın en uzun süresi (sn)' => 'Temps le plus long pour une ou plusieurs réponses',
  'Hostinger istekleri ~60 sn\'de kesebilir; 50 önerilir.' => 'Hostinger peut réduire les requêtes à environ 60 s ; 50 est recommandé.',
  'Devirde bildirim gidecek numaralar' => 'Numéros notifiés lors du transfert',
  'Asistan bir sohbeti ekibe devredince bu numaralara aynı hattan WhatsApp mesajı gider: kişinin adı, telefonu, nedeni, son mesajları ve panel linki. Virgül ya da satır ile ayırın. Bu numaralarla asistan konuşmaz.' => 'Lorsque l\'assistant transmet un chat à l\'équipe, un message WhatsApp est envoyé à ces numéros depuis la même ligne : le nom du contact, son téléphone, la raison, les derniers messages et le lien du panneau. Séparez par des virgules ou des nouvelles lignes. L\'assistant ne parle pas à ces numéros.',
  'Kişi bunlardan birini yazınca asistan beklemeden yukarıdaki devir mesajını gönderir ve o sohbette kapanır. Boş bırakılırsa örnekteki liste kullanılır.' => 'Lorsque le contact en écrit un, l\'assistant envoie immédiatement le message de transfert ci-dessus et s\'éteint dans cette discussion. Si elle est laissée vide, la liste d\'exemples est utilisée.',
  'Asistana ek talimatlar' => 'Instructions supplémentaires pour l\'assistant',
  'Ör. Fidanların dikileceği yer: Kocaeli. Sertifikalar bağış onaylanınca gönderilir.' => 'Par ex. Des plants sont plantés à Kocaeli. Les certificats sont envoyés une fois le don confirmé.',
  'Kişi mesaj istemeyince gönderilen son mesaj' => 'Dernier message lorsqu\'un contact se désinscrit',
  'Kişi "bana mesaj atmayın" gibi bir şey yazınca asistan bu mesajı gönderir ve kişiyi kara listeye alır. Kara listedeki kişiye WhatsApp, e-posta ve SMS gitmez; listeyi Sohbetler › ☰ › Kara liste\'den yönetirsiniz.' => 'Si quelqu\'un écrit quelque chose comme « ne m\'envoie pas de message », l\'assistant envoie ce message et le bloque. Une personne inscrite sur la liste bloquée ne reçoit ni WhatsApp, ni e-mail, ni SMS ; gérez la liste sous Chats › ☰ › Liste de blocage.',
  'Kişi hafızası ve arka plan işleri' => 'Mémoire de contacts et tâches en arrière-plan',
  'Kişi hafızası: asistan kişinin kalıcı bilgilerini (hitap, yakınlarının adı, numaralar, tercihler) hatırlar; süresi dolan sohbetler özetlenir' => 'Mémoire des contacts : l\'assistant se souvient de détails durables (type d\'adresse, noms des proches, numéros, préférences) ; les discussions expirées sont résumées',
  'Sohbet kaç saat sessiz kalınca özetlensin' => 'Résumer une conversation après qu\'elle soit restée silencieuse pendant (heures)',
  'Aynı anda en fazla iş' => 'Nombre maximum d\'emplois en même temps',
  'Aynı anda cevap yazılabilecek kişi sayısı. Asistan cevapları her zaman önce gelir; cevap yazılan ya da sırada bekleyen kişi varken özet başlamaz. Her iş bir PHP işçisi kullanır: paylaşımlı hostingde sitelerin toplam işçi sınırının yarısını geçmeyin (ör. 60 işçide 20-30).' => 'À combien de personnes peuvent être répondues en même temps. Les réponses de l\'assistant viennent toujours en premier ; les résumés ne démarrent pas lorsque quelqu\'un reçoit une réponse ou attend. Chaque tâche utilise un travailleur PHP : sur un hébergement partagé, restez sous la moitié de la limite totale de travailleurs de vos sites (par exemple 20 à 30 sur 60 travailleurs).',
  'Yalnız cevaplara ayrılan işçi' => 'Ouvriers réservés aux réponses',
  'Bu kadar işçi hiçbir zaman özet ya da hatırlatıcı almaz.' => 'De nombreux travailleurs ne prennent jamais de résumés ou de rappels.',
  'Özet saatleri' => 'Heures récapitulatives',
  'Özetler yalnız bu saatler arasında yapılır (elle "Şimdi özetle" hariç). İkisi aynıysa her saat.' => 'Les résumés ne s\'exécutent qu\'entre ces heures (sauf un manuel "Résumer maintenant"). Si les deux sont identiques, à tout moment.',
  'Kişi sesli mesaj gönderirse asistan sesi metne çevirip cevap versin (metin panelde sistem satırı olarak da görünür)' => 'Lorsque quelqu\'un envoie un message vocal, l\'assistant le transforme en texte et répond (le texte apparaît également dans le panneau sous forme de ligne système)',
  'En uzun ses (sn)' => 'Message vocal le plus long (sec)',
  'Daha uzun seslerde asistan "ses çok uzun olduğu için dinleyemedik" der.' => 'Pour les messages plus longs, l\'assistant dit "le message vocal était trop long pour que nous puissions l\'écouter".',
  'Sesli mesaj modeli (isteğe bağlı)' => 'Modèle de message vocal (facultatif)',
  'Ses okuyan ucuz model (Gemini Flash Lite)' => 'Modèle audio bon marché (Gemini Flash Lite)',
  'Ses okuyan bir OpenRouter modeli olmalı (Claude ses okumaz). OpenRouter anahtarı gerekir.' => 'Doit être un modèle OpenRouter qui accepte l\'audio (ce n\'est pas le cas de Claude). Une clé OpenRouter est requise.',
  'Görseller' => 'Images',
  'Gerekince asistan görsel (tablo, rapor, şema) çizsin; WhatsApp\'a resim olarak gider, metin ayrıca gider' => 'Laissez l\'assistant dessiner une image lorsque cela est utile (tableau, rapport, diagramme) ; il va sur WhatsApp sous forme d\'image, le texte est envoyé séparément',
  'Flux AI görsel çeviricisi kullanılır (Flux AI & MCP › Ayarlar › Görseller).' => 'Le moteur de rendu d\'image Flux AI est utilisé (Flux AI & MCP › Paramètres › Images).',
  'Sunucuda görsel çevirici yok: Flux AI & MCP › Ayarlar › Görseller\'e Gotenberg adresi girin ya da Imagick (SVG) kurulsun. O zamana kadar asistan görsel çizmez.' => 'Pas de moteur de rendu d\'image sur le serveur : saisissez une adresse Gotenberg dans Flux AI & MCP › Paramètres › Images ou installez Imagick (SVG). Jusque-là, l\'assistant ne dessine pas d\'images.',
  'Flux AI 0.2.0 ya da sonrası kurulunca çalışır.' => 'Fonctionne une fois que Flux AI 0.2.0 ou version ultérieure est installé.',
  'Başkası adına bağış' => 'Don au nom de quelqu\'un',
  'Bağış başkası adınaysa ve o kişinin numarası verildiyse (kişi kartı ya da yazılı numara), ödeme onaylanınca sertifika o numaraya da WhatsApp\'tan gitsin' => 'Si le don est au nom d\'une autre personne et que son numéro a été donné (carte de contact ou numéro tapé), envoyez également le certificat à ce numéro sur WhatsApp une fois le paiement approuvé.',
  'Sertifikadan önce giden mesaj' => 'Message envoyé avant le certificat',
  'Ardından Flux Certificates\'daki WhatsApp sertifika mesajı gider. Değişkenler: {ad}, {bagisci}, {bagis}, {brand}.' => 'Ensuite, le message du certificat WhatsApp de Flux Certificates est envoyé. Variables :{ad},{bagisci},{bagis},{brand}.',
  'Kişi isterse asistan hatırlatıcı kurar (ör. "her ay fidan dikimini hatırlat", "her ay son projelerinizi gönderin", "her ay benden bir fidan iste"); zamanı gelince asistan mesajı yazıp gönderir' => 'Si une personne le demande, l\'assistant établit un rappel (par exemple "rappelle-moi la plantation d\'un jeune arbre chaque mois", "envoie-moi tes derniers projets chaque mois", "demande-moi un jeune arbre chaque mois"); à l\'échéance, l\'assistant écrit et envoie le message',
  'Saat söylenmezse' => 'Quand aucun temps n\'est donné',
  'Kişi başına en fazla' => 'Au maximum par personne',
  'Personel (Flux Roles)' => 'Personnel (rôles flux)',
  'Flux Roles 1.1.0 kurulunca çalışır: numarası Profil › WhatsApp numarası alanına yazılmış kullanıcılar asistanda yetkilerine göre ek araçlar kullanır.' => 'Fonctionne une fois Flux Roles 1.1.0 installé : les utilisateurs dont le numéro est défini dans Profil > Numéro WhatsApp obtiennent des outils d\'assistance supplémentaires en fonction de leurs autorisations.',
  'Personel numarasından yazana asistan yetkisine göre ek araçlar açsın (başkası adına bağış ve ödeme linki, bağışçılarım, genel rapor)' => 'Donner aux effectifs des outils d\'assistance supplémentaires avec autorisation (don au nom d\'une personne avec lien de paiement, mes donateurs, rapport général)',
  'Referansı olduğu bağış ödenince ya da iptal olunca personele WhatsApp bildirimi gitsin' => 'Avertissez le personnel sur WhatsApp lorsqu\'un don qu\'ils ont recommandé est payé ou annulé',
  'Personel adına açılan bağışta bağışçıya ilk mesaj' => 'Premier message au donateur pour un don ouvert par le personnel',
  'Merhaba {ad} 🌱 {personel} aracılığıyla {bagis} bağış talebiniz alındı. Ödemeyi aşağıdaki bilgilerle yapabilirsiniz.' => 'Bonjour{ad}🌱 Votre demande de don{bagis}via{personel}a bien été reçue. Vous pouvez payer avec les détails ci-dessous.',
  'Ardından ödeme linki ve havale bilgileri gider. Değişkenler: {ad}, {adsoyad}, {personel}, {bagis}.' => 'Le lien de paiement et les coordonnées bancaires suivent. Variables :{ad},{adsoyad},{personel},{bagis}.',
  'Personelin referansı olduğu bağış ödenip sertifika oluşunca sertifika personele de WhatsApp\'tan gitsin (bağışçıya gittiği gibi)' => 'Lorsqu\'un don référé par un membre du personnel est payé et que ses attestations sont faites, envoyez-les également au membre du personnel sur WhatsApp (tout comme le donateur)',
  'Personele sertifikadan önce giden mesaj' => 'Message envoyé au membre du personnel avant l\'attestation',
  'Değişkenler: {ad}, {bagisci}, {bagis}, {no}, {brand}.' => 'Variables :{ad},{bagisci},{bagis},{no},{brand}.',
  'Personel bir bağışın sertifikasını en fazla kaç kez yeniden gönderebilir' => 'Combien de fois le personnel peut-il renvoyer un certificat de don',
  'Asistan göndermeden önce kime gideceğini yazıp onay ister. 0: kapalı.' => 'L\'assistant liste les destinataires et demande une confirmation avant l\'envoi. 0 : éteint.',
  'Kayıt sorgusunda kod doğrulama' => 'Vérification du code pour les recherches d\'enregistrements',
  'Kişi kayıtlarını sorar ve numarası gizliyse (ya da başka numara/e-postayla bağış yaptıysa) verdiği numaraya ya da e-postaya kod gönder; kod doğrulanınca onun kayıtları da gösterilir' => 'Lorsqu\'une personne demande son dossier et que son numéro est masqué (ou qu\'elle a fait un don avec un autre numéro/e-mail), envoyez un code au numéro ou à l\'e-mail qu\'elle donne ; une fois vérifiés, ses enregistrements sont également affichés',
  'Kod geçerliliği (dk)' => 'Validité du code (min)',
  'En fazla başarısız deneme' => 'Nombre maximal de tentatives infructueuses',
  'Gönderilemeyen, yanlış ya da süresi dolan kodlar sayılır. Sınırda kişiye aşağıdaki mesaj gider, ekibe haber verilir; asistan diğer sorulara cevap verir ama 24 saat kayıt bilgisi vermez.' => 'Les codes qui n\'ont pas pu être envoyés, les codes erronés et les codes expirés comptent. A la limite la personne reçoit le message ci-dessous et l\'équipe est avertie ; l\'assistant continue de répondre à d\'autres questions mais ne partage aucun détail d\'enregistrement pendant 24 heures.',
