  'Ayarlarda değiştir' => 'Modification des paramètres',
  '(boş)' => '(vide)',
  'Modele giden tam metin (örnek sohbet)' => 'Texte intégral envoyé au modèle (exemple de chat)',
  'Ek belgeler' => 'Documents supplémentaires',
  'Sık sorulan sorular, kampanya, dikim yerleri gibi bilgileri ayrı belgeler olarak ekleyin. Talimatta {{belge:kisa-ad}} yazarsanız belge oraya konur. "Gerektiğinde okur" seçilen belgeyi asistan yalnız konu açılınca okur; uzun belgeler için daha az maliyetlidir.' => 'Ajoutez des FAQ, des campagnes, des emplacements de plantation et des informations similaires dans des documents distincts. Si vous écrivez {{belge:kisa-ad}} dans les instructions, le document y est placé. Un document configuré pour « lire en cas de besoin » n\'est lu que lorsque le sujet est abordé, ce qui coûte moins cher pour les documents longs.',
