  'Ör. Ahmet\'in sohbetine bak, fiyat sorusuna daha kısa cevap versin. / Kurban bağışı sorulursa ekibe devretsin.' => 'Par ex. Regardez le chat d\'Ahmet et réduisez la réponse sur le prix. / Remettez le relais à l\'équipe lorsqu\'on l\'interroge sur les dons du Qurban.',
