  'Önce yazan kişilere cevap verilir; cevap yazılan ya da sırada bekleyen kişi varken özet başlamaz. {h} saat sessiz kalan sohbetler yalnız {w} arasında özetlenir. Aynı anda en fazla {m} iş çalışır, {r} işçi yalnız cevaplara ayrılır (benchmark bir iş sayılır). 5 sn\'de bir yenilenir.' => 'Les gens qui écrivent reçoivent une réponse en premier ; aucun résumé ne démarre lorsque quelqu\'un reçoit une réponse ou attend. Les discussions silencieuses pendant les heures{h}sont résumées uniquement entre{w}. Dans la plupart des tâches{m}exécutées en même temps, les travailleurs{r}sont réservés aux réponses (un test compte pour un). Actualisation toutes les 5 s.',
