  'Geçmiş {n} senaryo sonucunun ortalama token kullanımına göre; senaryo başına gerçek değer değişebilir.' => 'Basé sur l\'utilisation moyenne des jetons des résultats du scénario passé{n}; le coût réel par scénario peut varier.',
  'Henüz çalıştırma yok; varsayılan tahmin: müşteri mesajı başına ~{i} giriş / {o} çıkış token.' => 'Aucune course pour l\'instant ; estimation par défaut : ~ jetons d\'entrée{i}/ jetons de sortie{o}par message du donateur.',
  'Tahmin ücret limitini aşıyor; limit dolunca çalıştırma durur.' => 'L\'estimation dépasse la limite de coût ; la course s\'arrête lorsque la limite est atteinte.',
  'Yeni çalıştırma' => 'Nouvelle course',
  'Senaryolar test sohbetindeki gibi oynatılır: WhatsApp\'a mesaj gitmez, kayıt açılmaz. Model gerçekten çağrılır; ücret yapay zekâ hesabınızdan (OpenRouter ya da Anthropic) düşer ve limit dolunca çalıştırma durur.' => 'Les scénarios se déroulent comme dans le chat test : aucun message WhatsApp n\'est envoyé et aucun enregistrement n\'est créé. Le modèle s\'appelle vraiment ; le coût est facturé sur votre compte AI (OpenRouter ou Anthropic) et la course s\'arrête lorsque la limite est atteinte.',
