  'Mesajlar (sırayla)' => 'Messages (dans l\'ordre)',
  '{tur}, {birim} ve {brand} kullanılabilir. Yalnız müşteri mesajı varsa asistan her birine sırayla cevap verir. Asistan mesajı eklerseniz devam senaryosu olur: yazılan geçmiş hazır verilir, asistan yalnız en sondaki müşteri mesajına cevap verir.' => '{tur},{birim}et{brand}peuvent être utilisés. S\'il n\'y a que des messages clients, l\'assistant répond à chacun à tour de rôle. Si vous ajoutez des messages d\'assistant, cela devient un scénario de continuation : l\'historique écrit est donné tel quel et l\'assistant ne répond qu\'au dernier message client.',
  'Ör. payment_info, cancel_donation, receipt_check. Bu sitede kapalı araç bakılmaz.' => 'Par ex. payment_info, cancel_donation, reçu_check. Les outils désactivés sur ce site ne sont pas cochés.',
