  'Sonda durum' => 'État final',
  'Konuşma bitince test durumuna bakılır (bağış açıldı mı, iptal edildi mi, kod gitti mi…). Bu sitede kapalı araç bakılmaz.' => 'A la fin de la conversation, l\'état du test est vérifié (un don a-t-il été ouvert, annulé, un code envoyé...). Les outils désactivés sur ce site ne sont pas cochés.',
