  'uploads/flx-chat klasörüne yazılamıyor; gelen fotoğraf, ses ve belgeler kaydedilemez. Klasör izinlerini kontrol edin.' => 'Cannot write to uploads/flx-chat; les photos, notes vocales et documents entrants ne peuvent pas être enregistrés. Check folder permissions.',
  'Klasör koruması (.htaccess) yok; ilk medya kaydında oluşturulur.' => 'Protection des dossiers (.htaccess) manquante ; il est créé avec le premier média enregistré.',
