  'Temsilci rolündeki kullanıcı sayısı: %d.' => 'Utilisateurs avec le rôle d\'agent :%d.',
  'Temsilci rolünde kullanıcı yok; şimdilik yalnız yöneticiler kullanabilir.' => 'Aucun utilisateur n\'a le rôle d\'agent ; seuls les administrateurs peuvent l\'utiliser pour l\'instant.',
  'Panelin canlı güncellemesi' => 'Mises à jour du panneau en direct',
  'Son güncelleme isteği %1$s. Panel açıkken %2$d sn\'de bir yeni mesaj sorulur (arka plandaki sekmede 60 sn).' => 'Dernière demande de mise à jour%1$s. Lorsque le panneau est ouvert, il vérifie les nouveaux messages toutes les%2$ds (60 s dans un onglet en arrière-plan).',
