  '%s: bağlantı bilgisi' => '%s: détails de connexion',
  'Flux Mail bağlantısı kullanılıyor: %s.' => 'Utilisation de la connexion Flux Mail :%s.',
  'Hâlâ Flux Certificates\'daki eski sağlayıcı kullanılıyor; bağlantıyı Flux Mail\'e taşıyıp burada seçin.' => 'Vous utilisez toujours l\'ancien fournisseur dans les certificats Flux ; déplacez la connexion vers Flux Mail et sélectionnez-la ici.',
  'Flux Certificates\'daki Evolution sağlayıcısı kullanılıyor.' => 'Utilisation du fournisseur Evolution de Flux Certificates.',
  'API adresi, key ve instance bu eklentide girilmiş.' => 'L\'URL, la clé et l\'instance de l\'API sont saisies dans ce plugin.',
  '%s: hat durumu' => '%s: état de la ligne',
  'Telefon bağlı (son bilgi %s).' => 'Téléphone connecté (vu pour la dernière fois%s).',
  'Henüz denenmedi. "Bağlantıyı test et" düğmesine basın.' => 'Pas encore testé. Appuyez sur "Tester la connexion".',
  'Telefon bağlı değil (durum: %1$s, %2$s). "QR ile bağla" ile yeniden bağlayın.' => 'Téléphone non connecté (état :%1$s,%2$s). Reconnectez-vous avec « Connecter avec QR ».',
  '%s: Evolution API sürümü' => '%s: Version API Evolution',
  'Evolution API %s kullanılıyor. Gizli numaralı (@lid) kişilere cevap gitmeyebilir; sunucuyu 2.3 veya üstüne güncelleyin.' => 'L\'API Evolution%sest en cours d\'utilisation. Les réponses aux contacts à numéro masqué (@lid) peuvent échouer ; mettez à jour le serveur vers la version 2.3 ou ultérieure.',
  '%s: webhook (gelen mesajlar)' => '%s: webhook (messages entrants)',
  'Evolution\'dan hiç olay gelmedi; gelen mesajlar panele düşmez. "Webhook\'u kur" düğmesine basın.' => 'Aucun événement n\'est arrivé d\'Evolution ; les messages entrants ne s’afficheront pas dans le panneau. Appuyez sur « Configurer le webhook ».',
  'Son olay %s geldi. Hat sessiz olabilir; emin olmak için kendinize mesaj atın ya da webhook\'u yeniden kurun.' => 'Le dernier événement est arrivé%s. La ligne est peut-être simplement silencieuse ; envoyez-vous un message ou configurez à nouveau le webhook pour être sûr.',
  'Son olay %s geldi.' => 'Le dernier événement est arrivé%s.',
  'Flux Mail entegrasyonu' => 'Intégration de Flux Mail',
  'Etkin: WhatsApp bağlantıları İletişim › Bağlantılar\'dan alınır.' => 'Actif : les connexions WhatsApp proviennent de Communication > Connexions.',
  'Flux Mail etkin değil; bağlantılar Flux Certificates\'dan ya da bu eklentiden alınır.' => 'Flux Mail n\'est pas actif ; les connexions sont extraites des Certificats Flux ou de ce plugin.',
  'Flux Certificates entegrasyonu' => 'Intégration des Certificats Flux',
  'Etkin: sohbetten sertifika oluşturulup gönderilebilir.' => 'Actif : des certificats peuvent être créés et envoyés depuis les chats.',
  'Flux Certificates etkin değil; sohbetten sertifika işlemleri kapalı.' => 'Les Certificats Flux ne sont pas actifs ; les actions de certificat dans les discussions sont désactivées.',
  'Flux Donate entegrasyonu' => 'Intégration de Flux Donate',
  'Etkin: sohbetten bağış kaydı, dekont eşleştirme ve asistan kullanılabilir.' => 'Actif : les enregistrements de dons, l\'appariement des reçus et l\'assistant sont disponibles depuis les chats.',
  'Flux Donate etkin değil; bağış kaydı, dekont eşleştirme ve bağış asistanı kapalı.' => 'Flux Donate n’est pas actif ; les enregistrements de dons, l\'appariement des reçus et l\'assistant de don sont désactivés.',
  'Flux AI & MCP eklentisi kurulu değil; yapay zekâ özellikleri (öneri, asistan, dekont okuma, sesli mesaj, özet) kapalı. Flux AI\'yi kurup anahtarı oraya girin.' => 'Le plugin Flux AI & MCP n\'est pas installé ; Les fonctionnalités d\'IA (suggestions, assistant, lecture de reçus, messages vocaux, résumés) sont désactivées. Installez Flux AI et entrez la clé ici.',
  'Flux AI\'de anahtar girilmemiş; mesaj önerisi ve asistan kapalı.' => 'Aucune clé n\'a été saisie dans Flux AI ; les suggestions de messages et l\'assistant sont éteints.',
  'Anahtar var ama model seçilmemiş.' => 'Clé enregistrée mais aucun modèle sélectionné.',
  'Seçili model (%s) için Flux AI\'de sağlayıcının anahtarı girilmemiş.' => 'Aucune clé de fournisseur n\'a été saisie dans Flux AI pour le modèle sélectionné (%s).',
  'Anahtar kayıtlı, model: %s. Canlı deneme için "Bağlantıyı test et".' => 'Clé enregistrée, modèle :%s. Utilisez « Test de connexion » pour une vérification en direct.',
  'Bağış asistanı' => 'Assistante aux dons',
  'Kapalı.' => 'Éteint.',
  'Yapay zekâ anahtarı veya modeli eksik.' => 'La clé ou le modèle AI est manquant.',
  'Açık ama konuşmuyor: ' => 'Allumé mais ne répond pas :',
  'Açık. Sunulan bağış türleri: %s.' => 'Allumé. Types de dons proposés :%s.',
  '%s araç (tools) desteklemiyor; asistan için araç destekli bir model seçin.' => '%sne prend pas en charge les outils ; choisissez un modèle capable d’outils pour l’assistant.',
  'Dekont okuma modeli' => 'Modèle de lecture de reçu',
  '%s görsel okuyamıyor; dekont ön kontrolü çalışmaz. Görsel destekli bir dekont okuma modeli seçin.' => '%sne peut pas lire les images ; la vérification préalable du reçu ne fonctionnera pas. Choisissez un modèle de lecture de reçus compatible avec l’image.',
  'Asistanın ödeme bilgileri' => 'Détails de paiement de l\'assistant',
  'Alıcı adı ve IBAN tanımlı.' => 'Nom du destinataire et ensemble IBAN.',
  'Alıcı adı veya IBAN eksik; onaydan sonra havale bilgisi gönderilemez.' => 'Nom du destinataire ou IBAN manquant ; les coordonnées bancaires ne peuvent pas être envoyées après confirmation.',
  'Bağış sayfası linki' => 'Lien vers la page de don',
  'Bağış sayfası bulunamadı; asistan link göndermez.' => 'Page de don introuvable ; l\'assistant n\'enverra pas de lien.',
  'Arka plan istekleri' => 'Demandes d\'arrière-plan',
  'Site kendine arka plan isteği atamadı (%1$s: %2$s). Sıradaki cevaplar ve benchmark yavaş ilerleyebilir; güvenlik eklentisi ya da sunucu güvenlik duvarı /wp-json/flx-chat/ isteklerini engelliyor olabilir.' => 'Le site n\'a pas pu s\'envoyer une demande en arrière-plan (%1$s:%2$s). Les réponses en file d\'attente et l\'indice de référence peuvent évoluer lentement ; un plugin de sécurité ou le pare-feu du serveur peut bloquer les requêtes /wp-json/flx-chat/.',
  'hata' => 'erreur',
  'uyarı' => 'avertissement',
  'tamam' => 'ok',
  '{marka} doğrulama kodunuz: {kod}' => 'Votre code de vérification{marka}:{kod}',
  'Kod {dk} dakika geçerlidir. Bu kodu WhatsApp\'ta bizimle olan sohbete yazın. Bu isteği siz yapmadıysanız dikkate almayın.' => 'Le code est valable pour{dk}minutes. Tapez-le dans votre chat WhatsApp avec nous. Si vous ne l\'avez pas demandé, ignorez ce message.',
  'Bir sıkıntı oldu, ekibimiz en kısa sürede sizinle iletişime geçecek 🌱 Bu arada başka bir sorunuz olursa yazabilirsiniz.' => 'Quelque chose s\'est mal passé ; notre équipe vous contactera dans les plus brefs délais 🌱 En attendant, n\'hésitez pas à demander autre chose.',
  'Doğrulama denemesi başarısız (%1$d/%2$d): %3$s' => 'La tentative de vérification a échoué (%1$d/%2$d) :%3$s',
  'Kişi kayıtlarını görmek istedi, doğrulama yapılamadı; ekipten biri iletişime geçmeli' => 'La personne voulait voir ses dossiers mais n\'a pas pu être vérifiée ; quelqu\'un de l\'équipe devrait nous contacter',
  'e-posta gönderilemedi (Flux Mail › SMTP ayarlarını kontrol edin)' => 'l\'e-mail n\'a pas pu être envoyé (vérifiez Flux Mail › Paramètres SMTP)',
  'Asistan %1$s için doğrulama kodu gönderdi (%2$s).' => 'L\'assistant a envoyé un code de vérification pour%1$s(%2$s).',
  'kodun süresi doldu' => 'code expiré',
  'yanlış kod' => 'mauvais code',
  'Kişi %s için kodu doğruladı; kayıt sorgusuna eklendi.' => 'La personne a vérifié le code pour%s; il est ajouté à leurs recherches d\'enregistrements.',
  'Claude modelleri ses okuyamaz; Ayarlar › Yapay zekâ › Sesli mesaj modelinden ses okuyan bir OpenRouter modeli seçin.' => 'Les modèles Claude ne peuvent pas lire l\'audio ; choisissez un modèle OpenRouter compatible audio dans Paramètres > IA > Modèle de message vocal.',
  'Ses metne çevrilemedi.' => 'L\'audio n\'a pas pu être transcrit.',
  'Ses dosyası okunamadı.' => 'Le fichier audio n\'a pas pu être lu.',
  'Sesli mesaj (%1$s) metne çevrildi: %2$s' => 'Message vocal (%1$s) transcrit :%2$s',
  'Sesli mesaj (%1$s) dinlenemedi: %2$s' => 'Le message vocal (%1$s) n\'a pas pu être traité :%2$s',
  'Resmi WhatsApp Cloud API hattında bu işlem yok.' => 'Cette action n\'est pas disponible sur une ligne officielle de l\'API WhatsApp Cloud.',
  'WhatsApp 24 saat kuralı: kişi son 24 saatte yazmadığı için Cloud API serbest mesaj göndermiyor; yalnız onaylı şablon gider. Kişi yazınca yeniden deneyin.' => 'Règle des 24 heures WhatsApp : le contact n\'a pas écrit au cours des dernières 24 heures, l\'API Cloud n\'enverra donc pas de message libre ; seul un modèle approuvé peut être envoyé. Réessayez une fois qu\'ils auront écrit.',
  'Cloud API hattı için Flux Mail 1.10.0 veya üstü gerekli.' => 'Une ligne d\'API Cloud nécessite Flux Mail 1.10.0 ou version ultérieure.',
  'Cloud API bu adrese (gizli numara ya da grup) gönderemez.' => 'L\'API Cloud ne peut pas envoyer à cette adresse (numéro ou groupe masqué).',
  'Cloud API hesabına ulaşılamadı (İletişim › Bağlantılar).' => 'Impossible d\'accéder au compte Cloud API (İletişim › Connexions).',
  'Cloud API hattında QR yok; hesap İletişim › Bağlantılar\'da kurulur.' => 'Une ligne d\'API Cloud n\'a pas de code QR ; le compte est créé dans İletişim › Connexions.',
  'Dosya hazırlanamadı.' => 'Le fichier n\'a pas pu être préparé.',
  'Flux AI görsel desteği yok.' => 'Flux AI ne prend pas en charge les images.',
  'Görsel çevrilemedi.' => 'L\'image n\'a pas pu être rendue.',
  'Asistanın görseli gönderilemedi: ' => 'L\'image de l\'assistant n\'a pas pu être envoyée :',
  'Merhaba {first_name}, bağış kaydınızı oluşturduk: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'Ödemeyi yaptıktan sonra dekontu buradan gönderebilirsiniz. Teşekkür ederiz.' => 'Bonjour {first_name} , nous avons créé votre enregistrement de don : {donation} , total {amount} .' . chr(10) . '' . chr(10) . ' {bank} ' . chr(10) . '' . chr(10) . 'Après avoir payé, vous pouvez envoyer le reçu ici. Merci.',
  'Merhaba {first_name}, bağışınız kaydedildi: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . 'Desteğiniz için teşekkür ederiz.' => 'Bonjour{first_name}, votre don a été enregistré :{donation}, total{amount}.' . chr(10) . '' . chr(10) . 'Merci pour votre soutien.',
  'Bu senaryoyu oynatacak eklenti kapalı.' => 'Le plugin qui exécuterait ce scénario est inactif.',
  'Bu kullanıcının personel araçları yetkisi yok.' => 'Cet utilisateur n\'est pas autorisé à utiliser les outils du personnel.',
  '%1$s bu sohbeti personel olarak bağladı: %2$s' => '%1$sa associé ce chat à un membre du personnel%2$s',
  '%s sohbetin personel bağlantısını kaldırdı' => '%sa supprimé le lien du personnel de ce chat',
  'Sohbet personele bağlandı' => 'Chat lié à un membre du personnel',
  'Personel bağlantısı kaldırıldı' => 'Lien vers le personnel supprimé',
  '— Personel değil —' => '— Pas le personnel —',
  'WhatsApp bu kişinin numarasını gizliyor, asistan personeli numaradan tanıyamaz. Bu kişi ekibinizdense buradan bağlayın; asistan personel araçlarını açar.' => 'WhatsApp masque le numéro de cette personne, de sorte que l\'assistant ne peut pas reconnaître le personnel par son numéro. Si cette personne fait partie de votre équipe, associez-la ici et l\'assistant ouvrira les outils du personnel.',
  'Asistan personeli Flux Roles profilindeki numaradan tanır. Numara eşleşmiyorsa buradan bağlayabilirsiniz; numarası bilinen sohbette numara önceliklidir.' => 'L\'assistant reconnaît le personnel par le numéro indiqué dans son profil Flux Roles. Si le numéro ne correspond pas, vous pouvez les lier ici ; dans une conversation avec un numéro connu, le numéro vient en premier.',
  'Bu kanal şu an kullanılamıyor.' => 'Cette chaîne n\'est pas disponible pour le moment.',
  'Site sohbeti' => 'Discussion sur le site',
  'WhatsApp, site sohbeti ve diğer kanallardan gelen tüm mesajlar burada canlı görünür. Soldan bir sohbet seçin.' => 'Tous les messages de WhatsApp, du chat du site et d\'autres canaux apparaissent ici en direct. Choisissez une discussion sur la gauche.',
  'WhatsApp (Evolution API) çağrı merkezi: gelen ve giden mesajları canlı görün, yeni sohbet başlatın, hazır cevaplar, etiketler, atama, dahili notlar, otomatik yanıtlar; sohbetten bağış (Flux Donate) ve sertifika (Flux Certificates) kaydı, dekont eşleştirme. OpenRouter ile yapay zekâ cevap önerisi ve otomatik bağış asistanı.' => '[[Centre d\'appels WhatsApp (API Evolution) : consultez les messages entrants et sortants en direct, démarrez un nouveau chat, les réponses prédéfinies, les tags, les affectations, les notes internes, les réponses automatiques ; Enregistrement de dons (Flux Donate) et de certificats (Flux Certificates) à partir du chat, correspondance des reçus. Suggestion de réponse par intelligence artificielle et assistant de don automatique avec OpenRouter.',
  'WhatsApp (Evolution API) call center: see live incoming and outgoing messages, start new chat, canned replies, tags, assignment, internal notes, auto-replies; Donation (Flux Donate) and certificate (Flux Certificates) registration from chat, receipt matching. Artificial intelligence response suggestion and automatic donation assistant with OpenRouter.' => '[[Centre d\'appels WhatsApp (API Evolution) : consultez les messages entrants et sortants en direct, démarrez un nouveau chat, les réponses prédéfinies, les tags, les affectations, les notes internes, les réponses automatiques ; Enregistrement de dons (Flux Donate) et de certificats (Flux Certificates) à partir du chat, correspondance des reçus. Suggestion de réponse par intelligence artificielle et assistant de don automatique avec OpenRouter.',

 ),
);
